fn parse_bool(s: &str) -> std::result::Result<bool, String> {
    match s.to_lowercase().trim() {
        "true" | "1" | "yes" | "y" | "" => Ok(true),
        "false" | "0" | "no" | "n" => Ok(false),
        other => Err(format!("invalid boolean value: '{}'", other)),
    }
}

