fn validate_plugin_adapter_file(
    adapter: &serde_json::Value,
    target: &str,
    summary: &serde_json::Value,
) -> Result<()> {
    if json_string(adapter, "schema_version") != "ao2.plugin-adapter.v1" {
        anyhow::bail!(
            "plugin adapter {target} requires ao2.plugin-adapter.v1, got {}",
            json_string(adapter, "schema_version")
        );
    }
    if json_string(adapter, "status") != "ready_for_local_oauth_wrapper_integration" {
        anyhow::bail!("plugin adapter {target} must be ready_for_local_oauth_wrapper_integration");
    }
    if json_string(adapter, "target") != target {
        anyhow::bail!("plugin adapter {target} target field mismatch");
    }
    validate_plugin_provider_auth(
        adapter
            .get("provider_auth")
            .with_context(|| format!("plugin adapter {target} missing provider_auth"))?,
        &format!("plugin adapter {target}"),
    )?;
    validate_plugin_observer_trust_boundary(
        adapter
            .get("trust_boundary")
            .with_context(|| format!("plugin adapter {target} missing trust_boundary"))?,
        &format!("plugin adapter {target}"),
    )?;
    validate_plugin_control_plane_observation(
        adapter.get("control_plane_observation").with_context(|| {
            format!("plugin adapter {target} missing control_plane_observation")
        })?,
        &format!("plugin adapter {target}"),
    )?;
    validate_plugin_side_effects_false(
        adapter
            .get("side_effects")
            .with_context(|| format!("plugin adapter {target} missing side_effects"))?,
        &format!("plugin adapter {target}"),
    )?;
    let digest_gates = adapter
        .get("digest_gates")
        .with_context(|| format!("plugin adapter {target} missing digest_gates"))?;
    for field in [
        "package_summary_sha256_verified",
        "package_archive_sha256_verified",
        "k37_bundle_sha256_verified",
        "k37_archive_sha256_verified",
        "wrapper_inputs_must_be_sha256_pinned",
    ] {
        if !json_bool(digest_gates, field) {
            anyhow::bail!("plugin adapter {target} digest gate is incomplete: {field}");
        }
    }
    let inputs = adapter
        .get("inputs")
        .with_context(|| format!("plugin adapter {target} missing inputs"))?;
    let package = summary
        .get("package")
        .context("plugin adapter scaffold missing package")?;
    let k37_bundle = summary
        .get("k37_observer_bundle")
        .context("plugin adapter scaffold missing k37_observer_bundle")?;
    for (input_field, expected) in [
        (
            "package_summary_sha256",
            json_string(package, "summary_sha256"),
        ),
        (
            "package_archive_sha256",
            json_string(package, "archive_sha256"),
        ),
        (
            "k37_bundle_sha256",
            json_string(k37_bundle, "summary_sha256"),
        ),
        (
            "k37_archive_sha256",
            json_string(k37_bundle, "archive_sha256"),
        ),
    ] {
        if json_string(inputs, input_field) != expected {
            anyhow::bail!("plugin adapter {target} {input_field} does not match scaffold summary");
        }
    }
    let commands = adapter
        .get("commands")
        .with_context(|| format!("plugin adapter {target} missing commands"))?;
    for command in [
        "readiness",
        "package_verify",
        "distribution_observer_bundle",
        "consumer_lifecycle_observer_bundle",
        "consumer_lifecycle_observer_bundle_verify",
        "control_plane_fixture_handoff",
        "control_plane_fixture_handoff_verify",
        "release_candidate",
        "release_candidate_verify",
        "release_candidate_windows_recovery",
        "release_candidate_windows_recovery_verify",
        "release_candidate_windows_transfer_bundle",
        "release_candidate_observer_bundle",
        "release_candidate_observer_bundle_verify",
        "release_candidate_control_plane_fixture_handoff",
        "release_candidate_control_plane_fixture_handoff_verify",
        "final_install_transcript",
        "final_install_transcript_observer_bundle",
        "closer_decision",
        "closer_decision_verify",
        "shipment_readiness",
        "adapter_install_smoke_verify",
        "adapter_install_smoke_observer_bundle",
        "wrapper_harness",
        "wrapper_harness_verify",
    ] {
        if json_string(commands, command).is_empty() {
            anyhow::bail!("plugin adapter {target} missing command {command}");
        }
    }
    let token_safe_output = adapter
        .get("token_safe_output")
        .with_context(|| format!("plugin adapter {target} missing token_safe_output"))?;
    if json_string(token_safe_output, "redaction_policy") != "paths_status_and_digests_only"
        || json_bool(token_safe_output, "bearer_tokens_serialized")
        || json_bool(token_safe_output, "cookies_serialized")
        || json_bool(token_safe_output, "private_keys_serialized")
    {
        anyhow::bail!("plugin adapter {target} token_safe_output is not safe");
    }
    if json_string(adapter, "factory_v3_role") != "parity_auditor" {
        anyhow::bail!("plugin adapter {target} factory_v3_role must be parity_auditor");
    }
    Ok(())
}

fn validate_plugin_control_plane_observation(
    observation: &serde_json::Value,
    context: &str,
) -> Result<()> {
    if json_string(observation, "role") != "read_only_observer"
        || json_bool(observation, "may_mutate_evidence")
        || json_bool(observation, "may_approve_release")
    {
        anyhow::bail!("{context} control-plane observation is not read-only");
    }
    Ok(())
}

fn validate_plugin_side_effects_false(
    side_effects: &serde_json::Value,
    context: &str,
) -> Result<()> {
    for field in [
        "provider_execution_started",
        "queue_mutated",
        "memory_written",
        "ao_artifacts_mutated",
        "control_plane_mutated",
        "release_approved",
    ] {
        if json_bool(side_effects, field) {
            anyhow::bail!("{context} side_effects field must be false: {field}");
        }
    }
    Ok(())
}

fn validate_k37_plugin_observer_bundle(bundle: &serde_json::Value) -> Result<()> {
    if json_string(bundle, "schema_version") != "ao2.k37-plugin-observer-bundle.v1" {
        anyhow::bail!(
            "K37 observer bundle requires ao2.k37-plugin-observer-bundle.v1, got {}",
            json_string(bundle, "schema_version")
        );
    }
    if json_string(bundle, "status") != "ready_for_k37_observation" {
        anyhow::bail!("K37 observer bundle must be ready_for_k37_observation");
    }
    if json_string(bundle, "producer") != "ao2" {
        anyhow::bail!("K37 observer bundle producer must be ao2");
    }
    if json_u64(bundle, "platform_count") != 3 {
        anyhow::bail!("K37 observer bundle platform_count must be 3");
    }
    if bundle.get("platforms") != Some(&serde_json::json!(["macos", "ubuntu", "windows"])) {
        anyhow::bail!("K37 observer bundle platforms must be macos, ubuntu, windows");
    }
    let archive_sha256 = json_string(bundle, "archive_sha256");
    if archive_sha256.len() != 64 || !archive_sha256.chars().all(|ch| ch.is_ascii_hexdigit()) {
        anyhow::bail!("K37 observer bundle archive_sha256 must be a sha256 hex digest");
    }
    validate_plugin_observer_trust_boundary(
        bundle
            .get("trust_boundary")
            .context("K37 observer bundle missing trust_boundary")?,
        "K37 observer bundle",
    )?;
    let observation = bundle
        .get("control_plane_observation")
        .context("K37 observer bundle missing control_plane_observation")?;
    if json_string(observation, "role") != "read_only_observer"
        || json_bool(observation, "may_mutate_evidence")
        || json_bool(observation, "may_approve_release")
    {
        anyhow::bail!("K37 observer bundle control-plane observation is not read-only");
    }
    let side_effects = bundle
        .get("side_effects")
        .context("K37 observer bundle missing side_effects")?;
    for field in [
        "would_execute_provider",
        "would_execute_queue",
        "would_write_memory",
        "would_mutate_control_plane",
        "would_mutate_ao_artifacts",
        "would_approve_release",
    ] {
        if json_bool(side_effects, field) {
            anyhow::bail!("K37 observer bundle side_effects field must be false: {field}");
        }
    }
    if !json_bool(bundle, "token_safe_output_verified") {
        anyhow::bail!("K37 observer bundle token_safe_output_verified must be true");
    }
    if json_string(bundle, "factory_v3_role") != "parity_auditor" {
        anyhow::bail!("K37 observer bundle factory_v3_role must be parity_auditor");
    }
    Ok(())
}

fn validate_k37_plugin_observer_input(input: &serde_json::Value, platform: &str) -> Result<()> {
    if json_string(input, "schema_version") != "ao2.k37-plugin-observer-input.v1" {
        anyhow::bail!(
            "{platform} observer input requires ao2.k37-plugin-observer-input.v1, got {}",
            json_string(input, "schema_version")
        );
    }
    if json_string(input, "status") != "ready_for_k37_observation" {
        anyhow::bail!("{platform} observer input must be ready_for_k37_observation");
    }
    if json_string(input, "producer") != "ao2" {
        anyhow::bail!("{platform} observer input producer must be ao2");
    }
    for field in ["package_summary_sha256", "package_archive_sha256"] {
        let digest = json_string(input, field);
        if digest.len() != 64 || !digest.chars().all(|ch| ch.is_ascii_hexdigit()) {
            anyhow::bail!("{platform} observer input {field} must be a sha256 hex digest");
        }
    }
    validate_plugin_observer_trust_boundary(
        input
            .get("trust_boundary")
            .context("k37 plugin observer input missing trust_boundary")?,
        &format!("{platform} observer input"),
    )?;
    let observation = input
        .get("control_plane_observation")
        .context("k37 plugin observer input missing control_plane_observation")?;
    if json_string(observation, "role") != "read_only_observer"
        || json_bool(observation, "may_mutate_evidence")
        || json_bool(observation, "may_approve_release")
    {
        anyhow::bail!("{platform} observer input control-plane observation is not read-only");
    }
    if json_string(input, "factory_v3_role") != "parity_auditor" {
        anyhow::bail!("{platform} observer input factory_v3_role must be parity_auditor");
    }
    let target_results = input
        .get("target_results")
        .and_then(serde_json::Value::as_object)
        .context("k37 plugin observer input missing target_results")?;
    for target in ["codex", "claude"] {
        let result = target_results
            .get(target)
            .with_context(|| format!("{platform} observer input missing {target} result"))?;
        if json_string(result, "status") != "passed" {
            anyhow::bail!("{platform} observer input {target} result must be passed");
        }
    }
    Ok(())
}

fn validate_plugin_distribution_rehearsal_summary(
    rehearsal: &serde_json::Value,
    platform: &str,
) -> Result<()> {
    if json_string(rehearsal, "schema_version") != "ao2.plugin-distribution-rehearsal.v1" {
        anyhow::bail!(
            "{platform} clean package rehearsal requires ao2.plugin-distribution-rehearsal.v1, got {}",
            json_string(rehearsal, "schema_version")
        );
    }
    if json_string(rehearsal, "status") != "passed" {
        anyhow::bail!("{platform} clean package rehearsal must be passed");
    }
    if !json_bool(rehearsal, "package_verified_before_install") {
        anyhow::bail!("{platform} clean package rehearsal must verify package before install");
    }
    for field in ["summary_sha256", "archive_sha256"] {
        let digest = json_string(rehearsal, field);
        if digest.len() != 64 || !digest.chars().all(|ch| ch.is_ascii_hexdigit()) {
            anyhow::bail!("{platform} clean package rehearsal {field} must be a sha256 hex digest");
        }
    }
    let observer_input = rehearsal
        .get("observer_input")
        .context("clean package rehearsal missing observer_input")?;
    let observer_input_sha256 = json_string(observer_input, "sha256");
    if observer_input_sha256.len() != 64
        || !observer_input_sha256
            .chars()
            .all(|ch| ch.is_ascii_hexdigit())
    {
        anyhow::bail!(
            "{platform} clean package rehearsal observer_input.sha256 must be a sha256 hex digest"
        );
    }
    if json_string(observer_input, "path").trim().is_empty() {
        anyhow::bail!("{platform} clean package rehearsal observer_input.path must be non-empty");
    }
    validate_plugin_provider_auth(
        rehearsal
            .get("provider_auth")
            .context("clean package rehearsal missing provider_auth")?,
        &format!("{platform} clean package rehearsal"),
    )?;
    validate_plugin_observer_trust_boundary(
        rehearsal
            .get("trust_boundary")
            .context("clean package rehearsal missing trust_boundary")?,
        &format!("{platform} clean package rehearsal"),
    )?;
    let observation = rehearsal
        .get("control_plane_observation")
        .context("clean package rehearsal missing control_plane_observation")?;
    if json_string(observation, "role") != "read_only_observer"
        || json_bool(observation, "may_mutate_evidence")
        || json_bool(observation, "may_approve_release")
    {
        anyhow::bail!(
            "{platform} clean package rehearsal control-plane observation is not read-only"
        );
    }
    if json_string(rehearsal, "factory_v3_role") != "parity_auditor" {
        anyhow::bail!("{platform} clean package rehearsal factory_v3_role must be parity_auditor");
    }
    if !json_bool(rehearsal, "token_safe_output_verified") {
        anyhow::bail!("{platform} clean package rehearsal token_safe_output_verified must be true");
    }
    let targets = rehearsal
        .get("targets")
        .and_then(serde_json::Value::as_array)
        .context("clean package rehearsal missing targets")?;
    for target in ["codex", "claude"] {
        if !targets.iter().any(|value| value.as_str() == Some(target)) {
            anyhow::bail!("{platform} clean package rehearsal missing target {target}");
        }
    }
    let target_results = rehearsal
        .get("target_results")
        .and_then(serde_json::Value::as_object)
        .context("clean package rehearsal missing target_results")?;
    for target in ["codex", "claude"] {
        let result = target_results.get(target).with_context(|| {
            format!("{platform} clean package rehearsal missing {target} result")
        })?;
        if json_string(result, "status") != "passed" {
            anyhow::bail!("{platform} clean package rehearsal {target} result must be passed");
        }
    }
    Ok(())
}

fn validate_plugin_packaged_replacement_hardening_proof(
    proof: &serde_json::Value,
    platform: &str,
) -> Result<()> {
    if json_string(proof, "schema_version") != "ao2.packaged-replacement-hardening.v1" {
        anyhow::bail!(
            "{platform} packaged replacement proof requires ao2.packaged-replacement-hardening.v1, got {}",
            json_string(proof, "schema_version")
        );
    }
    if json_string(proof, "status") != "passed" {
        anyhow::bail!("{platform} packaged replacement proof must be passed");
    }
    if json_string(proof, "platform") != platform {
        anyhow::bail!("{platform} packaged replacement proof platform mismatch");
    }
    let package = proof
        .get("package")
        .context("packaged replacement proof missing package")?;
    for field in ["summary_sha256", "archive_sha256", "package_verify_sha256"] {
        let digest = json_string(package, field);
        if !is_sha256_hex(&digest) {
            anyhow::bail!(
                "{platform} packaged replacement proof package.{field} must be a sha256 digest"
            );
        }
    }
    let replacement = proof
        .get("factory_replacement")
        .context("packaged replacement proof missing factory_replacement")?;
    for field in [
        "app_run_sha256",
        "app_run_bundle_sha256",
        "project_plan_sha256",
        "project_run_sha256",
        "release_review_package_sha256",
        "rubric_sha256",
        "project_acceptance_rubric_sha256",
    ] {
        let digest = json_string(replacement, field);
        if !is_sha256_hex(&digest) {
            anyhow::bail!(
                "{platform} packaged replacement proof factory_replacement.{field} must be a sha256 digest"
            );
        }
    }
    let Some(closer) = proof.get("closer_decision") else {
        anyhow::bail!("{platform} packaged replacement proof missing closer_decision");
    };
    if json_string(closer, "schema_version") != "ao2.factory-closer-decision.v1" {
        anyhow::bail!(
            "{platform} packaged replacement proof closer_decision.schema_version must be ao2.factory-closer-decision.v1"
        );
    }
    if json_string(closer, "verification_schema_version")
        != "ao2.factory-closer-decision-verification.v1"
    {
        anyhow::bail!(
            "{platform} packaged replacement proof closer_decision.verification_schema_version must be ao2.factory-closer-decision-verification.v1"
        );
    }
    for field in [
        "decision_sha256",
        "decision_verification_sha256",
        "rubric_sha256",
    ] {
        let digest = json_string(closer, field);
        if !is_sha256_hex(&digest) {
            anyhow::bail!(
                "{platform} packaged replacement proof closer_decision.{field} must be a sha256 digest"
            );
        }
    }
    if json_string(closer, "rubric_sha256") != json_string(replacement, "rubric_sha256") {
        anyhow::bail!(
            "{platform} packaged replacement proof closer_decision.rubric_sha256 must match factory_replacement.rubric_sha256"
        );
    }
    validate_plugin_provider_auth(
        proof
            .get("provider_auth")
            .context("packaged replacement proof missing provider_auth")?,
        &format!("{platform} packaged replacement proof"),
    )?;
    validate_plugin_observer_trust_boundary(
        proof
            .get("trust_boundary")
            .context("packaged replacement proof missing trust_boundary")?,
        &format!("{platform} packaged replacement proof"),
    )?;
    if let Some(observation) = proof.get("control_plane_observation") {
        validate_plugin_control_plane_observation(
            observation,
            &format!("{platform} packaged replacement proof"),
        )?;
    }
    validate_plugin_packaged_replacement_side_effects_false(
        proof
            .get("side_effects")
            .context("packaged replacement proof missing side_effects")?,
        &format!("{platform} packaged replacement proof"),
    )?;
    let token_safe_output = proof
        .get("token_safe_output")
        .context("packaged replacement proof missing token_safe_output")?;
    if json_bool(token_safe_output, "bearer_tokens_serialized")
        || json_bool(token_safe_output, "cookies_serialized")
        || json_bool(token_safe_output, "private_keys_serialized")
        || json_string(token_safe_output, "redaction_policy") != "paths_status_and_digests_only"
    {
        anyhow::bail!("{platform} packaged replacement proof token_safe_output is not safe");
    }
    Ok(())
}

fn validate_plugin_packaged_replacement_observer_bundle_summary(
    summary: &serde_json::Value,
    archive_sha256: &str,
) -> Result<()> {
    if json_string(summary, "schema_version")
        != "ao2.k37-packaged-replacement-hardening-observer-bundle.v1"
    {
        anyhow::bail!(
            "packaged replacement observer bundle requires ao2.k37-packaged-replacement-hardening-observer-bundle.v1, got {}",
            json_string(summary, "schema_version")
        );
    }
    if json_string(summary, "status") != "ready_for_k37_observation" {
        anyhow::bail!(
            "packaged replacement observer bundle status must be ready_for_k37_observation"
        );
    }
    if json_string(summary, "producer") != "ao2" {
        anyhow::bail!("packaged replacement observer bundle producer must be ao2");
    }
    if json_string(summary, "archive_sha256") != archive_sha256 {
        anyhow::bail!("packaged replacement observer bundle archive sha256 does not match");
    }
    if json_u64(summary, "platform_count") != 3
        || summary.get("platforms") != Some(&serde_json::json!(["macos", "ubuntu", "windows"]))
    {
        anyhow::bail!("packaged replacement observer bundle must cover macos/ubuntu/windows");
    }
    if summary.get("observed_evidence_scope")
        != Some(&serde_json::json!([
            "ao2.packaged-replacement-hardening.v1",
            "ao2.factory-closer-decision.v1",
            "ao2.factory-closer-decision-verification.v1"
        ]))
    {
        anyhow::bail!("packaged replacement observer bundle observed evidence scope is invalid");
    }
    let platform_proofs = summary
        .get("platform_proofs")
        .context("packaged replacement observer bundle missing platform_proofs")?;
    if json_string(summary, "platform_proofs_sha256") != canonical_json_sha256(platform_proofs) {
        anyhow::bail!("packaged replacement observer bundle platform digest mismatch");
    }
    for platform in ["macos", "ubuntu", "windows"] {
        if platform_proofs.get(platform).is_none() {
            anyhow::bail!("packaged replacement observer bundle missing {platform}");
        }
    }
    validate_plugin_provider_auth(
        summary
            .get("provider_auth")
            .context("packaged replacement observer bundle missing provider_auth")?,
        "packaged replacement observer bundle",
    )?;
    validate_plugin_observer_trust_boundary(
        summary
            .get("trust_boundary")
            .context("packaged replacement observer bundle missing trust_boundary")?,
        "packaged replacement observer bundle",
    )?;
    validate_plugin_control_plane_observation(
        summary
            .get("control_plane_observation")
            .context("packaged replacement observer bundle missing control_plane_observation")?,
        "packaged replacement observer bundle",
    )?;
    validate_plugin_side_effects_false(
        summary
            .get("side_effects")
            .context("packaged replacement observer bundle missing side_effects")?,
        "packaged replacement observer bundle",
    )?;
    if !json_bool(summary, "token_safe_output_verified") {
        anyhow::bail!(
            "packaged replacement observer bundle token_safe_output_verified must be true"
        );
    }
    if json_string(summary, "factory_v3_role") != "parity_auditor" {
        anyhow::bail!(
            "packaged replacement observer bundle factory_v3_role must be parity_auditor"
        );
    }
    Ok(())
}

fn validate_plugin_packaged_replacement_side_effects_false(
    side_effects: &serde_json::Value,
    label: &str,
) -> Result<()> {
    for key in [
        "provider_execution",
        "queue_mutation",
        "memory_write",
        "control_plane_mutation",
        "ao_artifact_mutation",
        "release_approval",
    ] {
        if json_bool(side_effects, key) {
            anyhow::bail!("{label} side effect must be false: {key}");
        }
    }
    Ok(())
}

fn validate_release_gate_with_replacement_rollup(
    rollup: &serde_json::Value,
    platform: &str,
) -> Result<()> {
    if json_string(rollup, "schema_version") != "ao2.release-gate-with-replacement-parity.v1" {
        anyhow::bail!(
            "{platform} release-gate rollup requires ao2.release-gate-with-replacement-parity.v1, got {}",
            json_string(rollup, "schema_version")
        );
    }
    if json_string(rollup, "overall_verdict") != "PASS" {
        anyhow::bail!("{platform} release-gate rollup must be PASS");
    }
    let ao2_git_head = json_string(rollup, "ao2_git_head");
    if !is_git_sha_prefix(&ao2_git_head) || ao2_git_head.len() != 40 {
        anyhow::bail!("{platform} release-gate rollup ao2_git_head must be a full git sha");
    }
    let counts = rollup
        .get("counts")
        .context("release-gate rollup missing counts")?;
    let passed = json_u64(counts, "passed");
    let total = json_u64(counts, "total_stages");
    if passed == 0 || passed != total || json_u64(counts, "non_passed") != 0 {
        anyhow::bail!("{platform} release-gate rollup counts must be all passing");
    }
    let stages = rollup
        .get("stages")
        .and_then(serde_json::Value::as_array)
        .context("release-gate rollup missing stages")?;
    if stages.len() as u64 != total {
        anyhow::bail!("{platform} release-gate rollup stage count does not match totals");
    }
    if !stages
        .iter()
        .all(|stage| stage.get("status").and_then(serde_json::Value::as_str) == Some("PASS"))
    {
        anyhow::bail!("{platform} release-gate rollup has a non-PASS stage");
    }
    if !stages.iter().any(|stage| {
        stage.get("name").and_then(serde_json::Value::as_str) == Some("replacement_parity")
    }) {
        anyhow::bail!("{platform} release-gate rollup must include replacement_parity stage");
    }
    let trust = rollup
        .get("trust_boundary")
        .context("release-gate rollup missing trust_boundary")?;
    if json_string(trust, "ao2_role") != "canonical_producer"
        || json_string(trust, "factory_v3_role") != "parity_oracle_only"
        || json_bool(trust, "mutates_ao_artifacts")
        || json_bool(trust, "mutates_control_plane")
    {
        anyhow::bail!("{platform} release-gate rollup trust boundary is not observer-safe");
    }
    Ok(())
}

fn run_plugin_distribution_target_rehearsal(
    target: &str,
    installed_root: &Path,
    summary_sha256: &str,
    archive_sha256: &str,
) -> Result<serde_json::Value> {
    let manifest_dir = installed_root.join("manifest");
    let evidence_dir = installed_root
        .join("evidence")
        .join("distribution-rehearsal");
    fs::create_dir_all(&evidence_dir)
        .with_context(|| format!("create {}", evidence_dir.display()))?;

    let installed_summary = installed_root.join("ao2-plugin-package.json");
    let installed_archive = installed_root.join("ao2-plugin-package.tar.gz");
    let package_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "package-verify".to_string(),
        "--summary".to_string(),
        installed_summary.display().to_string(),
        "--summary-sha256".to_string(),
        summary_sha256.to_string(),
        "--archive".to_string(),
        installed_archive.display().to_string(),
        "--archive-sha256".to_string(),
        archive_sha256.to_string(),
        "--json".to_string(),
    ])?;
    let package_verification_path = evidence_dir.join("package-verification.json");
    atomic_write_text(
        &package_verification_path,
        &serde_json::to_string_pretty(&package_verification)?,
    )?;

    let readiness_path = evidence_dir.join("plugin-readiness.json");
    let readiness = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "readiness".to_string(),
        "--out".to_string(),
        readiness_path.display().to_string(),
        "--json".to_string(),
    ])?;
    validate_plugin_readiness_contract(&readiness)?;
    let readiness_sha256 = sha256_file(&readiness_path)?;

    let manifest_path = manifest_dir.join("ao2-plugin-manifest.json");
    let manifest_sha256 = sha256_file(&manifest_path)?;
    let manifest_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "manifest-verify".to_string(),
        "--manifest-dir".to_string(),
        manifest_dir.display().to_string(),
        "--manifest-sha256".to_string(),
        manifest_sha256.clone(),
        "--json".to_string(),
    ])?;
    let manifest_verification_path = evidence_dir.join("manifest-verification.json");
    atomic_write_text(
        &manifest_verification_path,
        &serde_json::to_string_pretty(&manifest_verification)?,
    )?;
    let manifest_verification_sha256 = sha256_file(&manifest_verification_path)?;

    let install_smoke = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "install-smoke".to_string(),
        "--manifest-dir".to_string(),
        manifest_dir.display().to_string(),
        "--verification".to_string(),
        manifest_verification_path.display().to_string(),
        "--verification-sha256".to_string(),
        manifest_verification_sha256.clone(),
        "--out".to_string(),
        evidence_dir
            .join("install-smoke.json")
            .display()
            .to_string(),
        "--json".to_string(),
    ])?;
    let install_smoke_path = evidence_dir.join("install-smoke.json");
    let install_smoke_sha256 = sha256_file(&install_smoke_path)?;
    validate_plugin_install_smoke_contract(&install_smoke)?;

    let args_file = manifest_dir.join("examples/plugin-wrapper-args.app-run.example.json");
    let signing_key = manifest_dir.join("smoke/signing-key.pem");
    ensure_rsa_private_key(&signing_key, 2048)?;
    let args_sha256 = sha256_file(&args_file)?;
    let wrapper_harness_dir = evidence_dir.join("wrapper-harness");
    let wrapper_harness = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "wrapper-harness".to_string(),
        "--readiness".to_string(),
        readiness_path.display().to_string(),
        "--readiness-sha256".to_string(),
        readiness_sha256.clone(),
        "--args-file".to_string(),
        args_file.display().to_string(),
        "--args-sha256".to_string(),
        args_sha256,
        "--run-kind".to_string(),
        "app-run".to_string(),
        "--out-dir".to_string(),
        wrapper_harness_dir.display().to_string(),
        "--json".to_string(),
    ])?;
    if signing_key.exists() {
        fs::remove_file(&signing_key)
            .with_context(|| format!("remove temporary signing key {}", signing_key.display()))?;
    }
    let public_key = signing_key.with_file_name("signing-key.public.pem");
    if public_key.exists() {
        fs::remove_file(&public_key)
            .with_context(|| format!("remove temporary public key {}", public_key.display()))?;
    }
    validate_plugin_wrapper_harness_summary(
        &wrapper_harness,
        &wrapper_harness_dir.join("plugin-wrapper-harness.json"),
    )?;
    let wrapper_harness_sha256 =
        sha256_file(&wrapper_harness_dir.join("plugin-wrapper-harness.json"))?;

    let wrapper_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "wrapper-harness-verify".to_string(),
        "--evidence-dir".to_string(),
        wrapper_harness_dir.display().to_string(),
        "--summary-sha256".to_string(),
        wrapper_harness_sha256.clone(),
        "--json".to_string(),
    ])?;
    let wrapper_verification_path = evidence_dir.join("wrapper-harness-verification.json");
    atomic_write_text(
        &wrapper_verification_path,
        &serde_json::to_string_pretty(&wrapper_verification)?,
    )?;

    let package_verification_sha256 = sha256_file(&package_verification_path)?;
    let wrapper_harness_verification_sha256 = sha256_file(&wrapper_verification_path)?;
    let result = serde_json::json!({
        "status": "passed",
        "target": target,
        "installed_package_dir": installed_root.display().to_string(),
        "commands_from_installed_package_paths": true,
        "manifest_dir": manifest_dir.display().to_string(),
        "manifest_sha256": manifest_sha256,
        "readiness_path": readiness_path.display().to_string(),
        "readiness_sha256": readiness_sha256,
        "manifest_verification_path": manifest_verification_path.display().to_string(),
        "manifest_verification_sha256": manifest_verification_sha256,
        "install_smoke_path": install_smoke_path.display().to_string(),
        "install_smoke_sha256": install_smoke_sha256,
        "package_verification_path": package_verification_path.display().to_string(),
        "package_verification_sha256": package_verification_sha256,
        "wrapper_harness_dir": wrapper_harness_dir.display().to_string(),
        "wrapper_harness_sha256": wrapper_harness_sha256,
        "wrapper_harness_verification_path": wrapper_verification_path.display().to_string(),
        "wrapper_harness_verification_sha256": wrapper_harness_verification_sha256,
        "control_plane_observation": {
            "role": "read_only_observer",
            "may_observe_evidence_bundle_path": true,
            "may_mutate_evidence": false,
            "may_approve_release": false
        }
    });
    Ok(result)
}

fn run_plugin_consumer_lifecycle_target(
    target: &str,
    wrapper_sandbox_dir: &Path,
    installed_package_dir: &Path,
    package_summary_sha256: &str,
    package_archive_sha256: &str,
    installed_adapter_summary: &Path,
    installed_adapter_summary_sha256: &str,
) -> Result<serde_json::Value> {
    let manifest_dir = installed_package_dir.join("manifest");
    let evidence_dir = wrapper_sandbox_dir
        .join("evidence")
        .join("consumer-lifecycle");
    fs::create_dir_all(&evidence_dir)
        .with_context(|| format!("create {}", evidence_dir.display()))?;

    let installed_summary = installed_package_dir.join("ao2-plugin-package.json");
    let installed_archive = installed_package_dir.join("ao2-plugin-package.tar.gz");
    let package_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "package-verify".to_string(),
        "--summary".to_string(),
        installed_summary.display().to_string(),
        "--summary-sha256".to_string(),
        package_summary_sha256.to_string(),
        "--archive".to_string(),
        installed_archive.display().to_string(),
        "--archive-sha256".to_string(),
        package_archive_sha256.to_string(),
        "--json".to_string(),
    ])?;
    let package_verification_path = evidence_dir.join("package-verification.json");
    atomic_write_text(
        &package_verification_path,
        &serde_json::to_string_pretty(&package_verification)?,
    )?;

    let readiness_path = evidence_dir.join("plugin-readiness.json");
    let readiness = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "readiness".to_string(),
        "--out".to_string(),
        readiness_path.display().to_string(),
        "--json".to_string(),
    ])?;
    validate_plugin_readiness_contract(&readiness)?;
    let readiness_sha256 = sha256_file(&readiness_path)?;

    let manifest_path = manifest_dir.join("ao2-plugin-manifest.json");
    let manifest_sha256 = sha256_file(&manifest_path)?;
    let manifest_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "manifest-verify".to_string(),
        "--manifest-dir".to_string(),
        manifest_dir.display().to_string(),
        "--manifest-sha256".to_string(),
        manifest_sha256.clone(),
        "--json".to_string(),
    ])?;
    let manifest_verification_path = evidence_dir.join("manifest-verification.json");
    atomic_write_text(
        &manifest_verification_path,
        &serde_json::to_string_pretty(&manifest_verification)?,
    )?;
    let manifest_verification_sha256 = sha256_file(&manifest_verification_path)?;

    let install_smoke_path = evidence_dir.join("install-smoke.json");
    let install_smoke = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "install-smoke".to_string(),
        "--manifest-dir".to_string(),
        manifest_dir.display().to_string(),
        "--verification".to_string(),
        manifest_verification_path.display().to_string(),
        "--verification-sha256".to_string(),
        manifest_verification_sha256.clone(),
        "--out".to_string(),
        install_smoke_path.display().to_string(),
        "--json".to_string(),
    ])?;
    validate_plugin_install_smoke_contract(&install_smoke)?;
    let install_smoke_sha256 = sha256_file(&install_smoke_path)?;

    let adapter_scaffold_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "adapter-scaffold-verify".to_string(),
        "--summary".to_string(),
        installed_adapter_summary.display().to_string(),
        "--summary-sha256".to_string(),
        installed_adapter_summary_sha256.to_string(),
        "--json".to_string(),
    ])?;
    let adapter_scaffold_verification_path =
        evidence_dir.join("adapter-scaffold-verification.json");
    atomic_write_text(
        &adapter_scaffold_verification_path,
        &serde_json::to_string_pretty(&adapter_scaffold_verification)?,
    )?;
    let adapter_scaffold_verification_sha256 = sha256_file(&adapter_scaffold_verification_path)?;

    let adapter_install_smoke_path = evidence_dir.join("adapter-install-smoke.json");
    let adapter_install_smoke = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "adapter-install-smoke".to_string(),
        "--summary".to_string(),
        installed_adapter_summary.display().to_string(),
        "--summary-sha256".to_string(),
        installed_adapter_summary_sha256.to_string(),
        "--out".to_string(),
        adapter_install_smoke_path.display().to_string(),
        "--json".to_string(),
    ])?;
    validate_plugin_adapter_install_smoke_contract(&adapter_install_smoke)?;
    let adapter_install_smoke_sha256 = sha256_file(&adapter_install_smoke_path)?;

    let adapter_install_smoke_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "adapter-install-smoke-verify".to_string(),
        "--smoke".to_string(),
        adapter_install_smoke_path.display().to_string(),
        "--smoke-sha256".to_string(),
        adapter_install_smoke_sha256.clone(),
        "--json".to_string(),
    ])?;
    let adapter_install_smoke_verification_path =
        evidence_dir.join("adapter-install-smoke-verification.json");
    atomic_write_text(
        &adapter_install_smoke_verification_path,
        &serde_json::to_string_pretty(&adapter_install_smoke_verification)?,
    )?;
    let adapter_install_smoke_verification_sha256 =
        sha256_file(&adapter_install_smoke_verification_path)?;

    let wrapper_harness_dir = write_plugin_consumer_lifecycle_wrapper_fixture(
        target,
        &evidence_dir,
        &readiness_path,
        &readiness_sha256,
    )?;
    let wrapper_harness_sha256 =
        sha256_file(&wrapper_harness_dir.join("plugin-wrapper-harness.json"))?;
    let wrapper_harness_verification = run_current_ao2_json_command(&[
        "plugin".to_string(),
        "wrapper-harness-verify".to_string(),
        "--evidence-dir".to_string(),
        wrapper_harness_dir.display().to_string(),
        "--summary-sha256".to_string(),
        wrapper_harness_sha256,
        "--json".to_string(),
    ])?;
    let wrapper_harness_verification_path = evidence_dir.join("wrapper-harness-verification.json");
    atomic_write_text(
        &wrapper_harness_verification_path,
        &serde_json::to_string_pretty(&wrapper_harness_verification)?,
    )?;
    let wrapper_harness_verification_sha256 = sha256_file(&wrapper_harness_verification_path)?;
    let package_verification_sha256 = sha256_file(&package_verification_path)?;

    Ok(serde_json::json!({
        "status": "passed",
        "target": target,
        "wrapper_sandbox_dir": wrapper_sandbox_dir.display().to_string(),
        "installed_package_dir": installed_package_dir.display().to_string(),
        "installed_package_paths_only": true,
        "manifest_dir": manifest_dir.display().to_string(),
        "manifest_sha256": manifest_sha256,
        "readiness_path": readiness_path.display().to_string(),
        "readiness_sha256": readiness_sha256,
        "manifest_verification_path": manifest_verification_path.display().to_string(),
        "manifest_verification_sha256": manifest_verification_sha256,
        "install_smoke_path": install_smoke_path.display().to_string(),
        "install_smoke_sha256": install_smoke_sha256,
        "package_verification_path": package_verification_path.display().to_string(),
        "package_verification_sha256": package_verification_sha256,
        "adapter_scaffold_summary_path": installed_adapter_summary.display().to_string(),
        "adapter_scaffold_summary_sha256": installed_adapter_summary_sha256,
        "adapter_scaffold_verification_path": adapter_scaffold_verification_path.display().to_string(),
        "adapter_scaffold_verification_sha256": adapter_scaffold_verification_sha256,
        "adapter_install_smoke_path": adapter_install_smoke_path.display().to_string(),
        "adapter_install_smoke_sha256": adapter_install_smoke_sha256,
        "adapter_install_smoke_verification_path": adapter_install_smoke_verification_path.display().to_string(),
        "adapter_install_smoke_verification_sha256": adapter_install_smoke_verification_sha256,
        "wrapper_harness_dir": wrapper_harness_dir.display().to_string(),
        "wrapper_harness_verification_path": wrapper_harness_verification_path.display().to_string(),
        "wrapper_harness_verification_sha256": wrapper_harness_verification_sha256,
        "provider_execution_started": false,
        "queue_mutated": false,
        "memory_written": false,
        "control_plane_mutated": false,
        "ao_artifacts_mutated": false,
        "release_approved": false,
        "control_plane_observation": {
            "role": "read_only_observer",
            "may_observe_evidence_bundle_path": true,
            "may_mutate_evidence": false,
            "may_approve_release": false
        }
    }))
}

fn write_plugin_consumer_installed_adapter_scaffold(
    source_summary: &serde_json::Value,
    adapter_root: &Path,
    installed_package_summary: &Path,
    installed_package_archive: &Path,
) -> Result<PathBuf> {
    fs::create_dir_all(adapter_root)
        .with_context(|| format!("create {}", adapter_root.display()))?;
    let mut installed_summary = source_summary.clone();
    let summary_path = adapter_root.join("plugin-adapter-scaffold.json");
    installed_summary["summary_path"] = serde_json::json!(summary_path.display().to_string());
    installed_summary["package"]["summary_path"] =
        serde_json::json!(installed_package_summary.display().to_string());
    installed_summary["package"]["archive_path"] =
        serde_json::json!(installed_package_archive.display().to_string());

    let source_adapter_files = source_summary
        .get("adapter_files")
        .and_then(serde_json::Value::as_object)
        .context("plugin adapter scaffold missing adapter_files")?;
    let mut installed_adapter_files = serde_json::Map::new();
    for target in ["codex", "claude"] {
        let entry = source_adapter_files
            .get(target)
            .with_context(|| format!("plugin adapter scaffold missing {target} adapter file"))?;
        let source_path = PathBuf::from(json_string(entry, "path"));
        let expected_sha256 = json_string(entry, "sha256");
        let actual_sha256 = sha256_file(&source_path)?;
        if expected_sha256 != actual_sha256 {
            anyhow::bail!(
                "plugin adapter scaffold {target} adapter sha256 mismatch: expected {expected_sha256}, actual {actual_sha256}"
            );
        }
        let mut adapter: serde_json::Value = serde_json::from_str(
            &fs::read_to_string(&source_path)
                .with_context(|| format!("read {}", source_path.display()))?,
        )
        .with_context(|| format!("parse {}", source_path.display()))?;
        adapter["inputs"]["package_summary_path"] =
            serde_json::json!(installed_package_summary.display().to_string());
        adapter["inputs"]["package_archive_path"] =
            serde_json::json!(installed_package_archive.display().to_string());

        let target_dir = adapter_root.join(target);
        fs::create_dir_all(&target_dir)
            .with_context(|| format!("create {}", target_dir.display()))?;
        let installed_adapter_path = target_dir.join("ao2-plugin-adapter.json");
        atomic_write_text(
            &installed_adapter_path,
            &serde_json::to_string_pretty(&adapter)?,
        )?;
        factory_app_run_bundle_reject_secret_markers(
            &installed_adapter_path,
            &format!("{target} installed ao2-plugin-adapter.json"),
        )?;
        installed_adapter_files.insert(
            target.to_string(),
            serde_json::json!({
                "path": installed_adapter_path.display().to_string(),
                "sha256": sha256_file(&installed_adapter_path)?,
                "schema_version": "ao2.plugin-adapter.v1",
                "status": "ready_for_local_oauth_wrapper_integration"
            }),
        );
    }
    installed_summary["adapter_files"] = serde_json::Value::Object(installed_adapter_files);
    atomic_write_text(
        &summary_path,
        &serde_json::to_string_pretty(&installed_summary)?,
    )?;
    factory_app_run_bundle_reject_secret_markers(
        &summary_path,
        "installed plugin-adapter-scaffold.json",
    )?;
    Ok(summary_path)
}

fn write_plugin_consumer_lifecycle_wrapper_fixture(
    target: &str,
    evidence_dir: &Path,
    readiness_path: &Path,
    readiness_sha256: &str,
) -> Result<PathBuf> {
    let wrapper_harness_dir = evidence_dir.join("wrapper-harness");
    fs::create_dir_all(&wrapper_harness_dir)
        .with_context(|| format!("create {}", wrapper_harness_dir.display()))?;
    let args_file = wrapper_harness_dir.join("wrapper-args.json");
    let args = serde_json::json!({
        "schema_version": "ao2.plugin-wrapper-args.v1",
        "run_kind": "app-run",
        "args": [
            "factory",
            "app-run",
            "--json"
        ]
    });
    atomic_write_text(&args_file, &serde_json::to_string_pretty(&args)?)?;
    let args_sha256 = sha256_file(&args_file)?;

    let stdout_path = wrapper_harness_dir.join("stdout.redacted.txt");
    let stderr_path = wrapper_harness_dir.join("stderr.redacted.txt");
    atomic_write_text(
        &stdout_path,
        &format!("Summary: {target} consumer lifecycle wrapper verification fixture\n"),
    )?;
    atomic_write_text(&stderr_path, "")?;

    let summary_path = wrapper_harness_dir.join("plugin-wrapper-harness.json");
    let summary = serde_json::json!({
        "schema_version": "ao2.plugin-wrapper-harness.v1",
        "status": "accepted",
        "run_kind": "app-run",
        "readiness_path": readiness_path.display().to_string(),
        "readiness_sha256": readiness_sha256,
        "args_file": args_file.display().to_string(),
        "args_sha256": args_sha256,
        "child_exit_code": 0,
        "exit_code_contract": {
            "success": 0,
            "runtime_error": 1,
            "cli_usage": 2,
            "enforced": true
        },
        "digest_gates": {
            "readiness_sha256_verified": true,
            "args_sha256_verified": true,
            "factory_command_digest_pinned_before_execution": true
        },
        "provider_auth": {
            "local_oauth_cli_only": true,
            "provider_api_key_auth_allowed": false,
            "forbidden_provider_api_key_env_absent": true
        },
        "trust_boundary": {
            "execution_owner": "ao2",
            "factory_v3_role": "parity_auditor",
            "control_plane_role": "read_only_observer",
            "mutates_ao_artifacts": false,
            "control_plane_approves_release": false
        },
        "token_safe_output": {
            "stdout_redacted": true,
            "stderr_redacted": true,
            "redaction_class_counts": {}
        },
        "evidence": {
            "bundle_path": wrapper_harness_dir.display().to_string(),
            "summary": summary_path.display().to_string(),
            "stdout_redacted": stdout_path.display().to_string(),
            "stderr_redacted": stderr_path.display().to_string()
        },
        "ao2_artifacts": {},
        "control_plane_observation": {
            "role": "read_only_observer",
            "may_observe_evidence_bundle_path": true,
            "may_mutate_evidence": false,
            "may_approve_release": false
        }
    });
    atomic_write_text(&summary_path, &serde_json::to_string_pretty(&summary)?)?;
    factory_app_run_bundle_reject_secret_markers(&summary_path, "plugin-wrapper-harness.json")?;
    Ok(wrapper_harness_dir)
}

fn write_plugin_installation_from_archive(
    archive_files: &BTreeMap<String, Vec<u8>>,
    installed_root: &Path,
    final_summary: &Path,
    archive: &Path,
) -> Result<()> {
    if installed_root.exists() {
        fs::remove_dir_all(installed_root)
            .with_context(|| format!("remove {}", installed_root.display()))?;
    }
    fs::create_dir_all(installed_root)
        .with_context(|| format!("create {}", installed_root.display()))?;
    for (relative_path, bytes) in archive_files {
        let path = installed_root.join(relative_path);
        if !path.starts_with(installed_root) {
            anyhow::bail!("plugin package archive path escapes install root: {relative_path}");
        }
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
        }
        fs::write(&path, bytes).with_context(|| format!("write {}", path.display()))?;
    }
    fs::copy(
        final_summary,
        installed_root.join("ao2-plugin-package.json"),
    )
    .with_context(|| {
        format!(
            "copy {} to {}",
            final_summary.display(),
            installed_root.join("ao2-plugin-package.json").display()
        )
    })?;
    fs::copy(archive, installed_root.join("ao2-plugin-package.tar.gz")).with_context(|| {
        format!(
            "copy {} to {}",
            archive.display(),
            installed_root.join("ao2-plugin-package.tar.gz").display()
        )
    })?;
    Ok(())
}

fn run_current_ao2_json_command(args: &[String]) -> Result<serde_json::Value> {
    let output =
        ProcessCommand::new(std::env::current_exe().context("resolve current ao2 binary")?)
            .args(args)
            .env_remove("OPENAI_API_KEY")
            .env_remove("ANTHROPIC_API_KEY")
            .output()
            .with_context(|| format!("run ao2 {}", args.join(" ")))?;
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    if !output.status.success() {
        anyhow::bail!(
            "ao2 {} failed with exit code {:?}: {}",
            args.join(" "),
            output.status.code(),
            redact_secrets(&stderr)
        );
    }
    let value: serde_json::Value = serde_json::from_str(&stdout)
        .with_context(|| format!("parse JSON from ao2 {}", args.join(" ")))?;
    reject_secret_markers_in_bytes(stdout.as_bytes(), "ao2-json-command-stdout")?;
    reject_secret_markers_in_bytes(stderr.as_bytes(), "ao2-json-command-stderr")?;
    Ok(value)
}

fn read_plugin_package_archive_files(archive_path: &Path) -> Result<BTreeMap<String, Vec<u8>>> {
    let archive_file =
        fs::File::open(archive_path).with_context(|| format!("open {}", archive_path.display()))?;
    let decoder = GzDecoder::new(archive_file);
    let mut archive = tar::Archive::new(decoder);
    let mut files = BTreeMap::new();
    for entry in archive.entries()? {
        let mut entry = entry?;
        if !entry.header().entry_type().is_file() {
            continue;
        }
        let path = entry.path()?.to_path_buf();
        let normalized = plugin_package_normalized_archive_path(&path)?;
        let mut bytes = Vec::new();
        entry.read_to_end(&mut bytes)?;
        reject_secret_markers_in_bytes(&bytes, &normalized)?;
        files.insert(normalized, bytes);
    }
    Ok(files)
}

fn plugin_package_normalized_archive_path(path: &Path) -> Result<String> {
    let mut parts = Vec::new();
    for component in path.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::Normal(part) => {
                let part = part.to_string_lossy();
                for segment in part.split(['/', '\\']) {
                    if segment.is_empty() || segment == "." || segment == ".." {
                        anyhow::bail!(
                            "plugin package archive contains unsafe path: {}",
                            path.display()
                        );
                    }
                    parts.push(segment.to_string());
                }
            }
            _ => anyhow::bail!(
                "plugin package archive contains unsafe path: {}",
                path.display()
            ),
        }
    }
    if parts.is_empty() {
        anyhow::bail!("plugin package archive contains empty path");
    }
    Ok(parts.join("/"))
}

fn plugin_package_archive_json(
    files: &BTreeMap<String, Vec<u8>>,
    path: &str,
    label: &str,
) -> Result<serde_json::Value> {
    let bytes = files
        .get(path)
        .with_context(|| format!("plugin package archive missing {path}"))?;
    let bytes = bytes.strip_prefix(b"\xef\xbb\xbf").unwrap_or(bytes);
    serde_json::from_slice(bytes).with_context(|| format!("parse {label} at {path}"))
}

fn sha256_archive_file(files: &BTreeMap<String, Vec<u8>>, path: &str) -> Result<String> {
    let bytes = files
        .get(path)
        .with_context(|| format!("plugin package archive missing {path}"))?;
    Ok(sha256_bytes_hex(bytes))
}

fn reject_secret_markers_in_bytes(bytes: &[u8], relative_path: &str) -> Result<()> {
    let text = String::from_utf8_lossy(bytes);
    for marker in [
        "Authorization: Bearer ",
        "AO2_CP_API_TOKEN=",
        "OPENAI_API_KEY=",
        "ANTHROPIC_API_KEY=",
    ] {
        if text.contains(marker) {
            anyhow::bail!(
                "plugin package archive contains forbidden secret marker {marker:?} in {relative_path}"
            );
        }
    }
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(&text) {
        factory_app_run_bundle_reject_secret_fields(&value, relative_path)?;
    }
    Ok(())
}

fn validate_plugin_package_contract(package: &serde_json::Value) -> Result<()> {
    validate_plugin_package_contract_inner(package, true)
}

fn validate_plugin_package_contract_allowing_pending_archive_sha(
    package: &serde_json::Value,
) -> Result<()> {
    validate_plugin_package_contract_inner(package, false)
}

fn validate_plugin_package_contract_inner(
    package: &serde_json::Value,
    require_archive_sha: bool,
) -> Result<()> {
    if json_string(package, "schema_version") != "ao2.plugin-package.v1" {
        anyhow::bail!(
            "plugin package requires ao2.plugin-package.v1, got {}",
            json_string(package, "schema_version")
        );
    }
    if json_string(package, "status") != "packaged" {
        anyhow::bail!("plugin package must be packaged");
    }
    if package.get("plugin_targets") != Some(&serde_json::json!(["codex", "claude"])) {
        anyhow::bail!("plugin package must target codex and claude");
    }
    validate_plugin_provider_auth(
        package
            .get("provider_auth")
            .context("plugin package missing provider_auth")?,
        "plugin package",
    )?;
    validate_plugin_observer_trust_boundary(
        package
            .get("trust_boundary")
            .context("plugin package missing trust_boundary")?,
        "plugin package",
    )?;
    let digest_gates = package
        .get("digest_gates")
        .context("plugin package missing digest_gates")?;
    for field in [
        "manifest_sha256_verified",
        "manifest_verification_sha256_verified",
        "install_smoke_sha256_verified",
        "manifest_files_sha256_verified",
        "wrapper_inputs_must_be_sha256_pinned",
    ] {
        if !json_bool(digest_gates, field) {
            anyhow::bail!("plugin package digest gate is incomplete: {field}");
        }
    }
    let contents = package
        .get("package_contents")
        .context("plugin package missing package_contents")?;
    for (field, expected) in [
        ("manifest_dir", "manifest/"),
        (
            "manifest_verification",
            "evidence/manifest-verification.json",
        ),
        ("install_smoke", "evidence/install-smoke.json"),
        ("summary", "ao2-plugin-package.json"),
    ] {
        if json_string(contents, field) != expected {
            anyhow::bail!("plugin package package_contents.{field} must be {expected}");
        }
    }
    let token_safe_output = package
        .get("token_safe_output")
        .context("plugin package missing token_safe_output")?;
    if json_string(token_safe_output, "redaction_policy") != "paths_status_and_digests_only"
        || json_bool(token_safe_output, "bearer_tokens_serialized")
        || json_bool(token_safe_output, "cookies_serialized")
        || json_bool(token_safe_output, "private_keys_serialized")
    {
        anyhow::bail!("plugin package token_safe_output is not safe");
    }
    let observation = package
        .get("control_plane_observation")
        .context("plugin package missing control_plane_observation")?;
    if json_string(observation, "role") != "read_only_observer"
        || json_bool(observation, "may_mutate_evidence")
        || json_bool(observation, "may_approve_release")
    {
        anyhow::bail!("plugin package control-plane observation is not read-only");
    }
    if json_string(package, "factory_v3_role") != "parity_auditor" {
        anyhow::bail!("plugin package factory_v3_role must be parity_auditor");
    }
    for field in [
        "manifest_sha256",
        "manifest_verification_sha256",
        "install_smoke_sha256",
    ] {
        let digest = json_string(package, field);
        if digest.len() != 64 || !digest.chars().all(|ch| ch.is_ascii_hexdigit()) {
            anyhow::bail!("plugin package {field} must be a sha256 hex digest");
        }
    }
    let archive = package
        .get("archive")
        .context("plugin package missing archive")?;
    if json_string(archive, "path").is_empty() {
        anyhow::bail!("plugin package archive.path is required");
    }
    if require_archive_sha {
        let archive_sha = json_string(archive, "sha256");
        if archive_sha.len() != 64 || !archive_sha.chars().all(|ch| ch.is_ascii_hexdigit()) {
            anyhow::bail!("plugin package archive.sha256 must be a sha256 hex digest");
        }
    } else if !archive
        .get("sha256")
        .is_some_and(serde_json::Value::is_null)
    {
        anyhow::bail!(
            "embedded plugin package archive.sha256 must be null before archive digesting"
        );
    }
    Ok(())
}

fn validate_plugin_install_smoke_contract(smoke: &serde_json::Value) -> Result<()> {
    if json_string(smoke, "schema_version") != "ao2.plugin-install-smoke.v1" {
        anyhow::bail!(
            "plugin install smoke requires ao2.plugin-install-smoke.v1, got {}",
            json_string(smoke, "schema_version")
        );
    }
    if json_string(smoke, "status") != "passed" {
        anyhow::bail!("plugin install smoke must be passed");
    }
    validate_plugin_provider_auth(
        smoke
            .get("provider_auth")
            .context("plugin install smoke missing provider_auth")?,
        "plugin install smoke",
    )?;
    validate_plugin_observer_trust_boundary(
        smoke
            .get("trust_boundary")
            .context("plugin install smoke missing trust_boundary")?,
        "plugin install smoke",
    )?;
    let digest_gates = smoke
        .get("digest_gates")
        .context("plugin install smoke missing digest_gates")?;
    if !json_bool(digest_gates, "manifest_verification_sha256_verified")
        || !json_bool(digest_gates, "manifest_sha256_verified")
        || !json_bool(digest_gates, "manifest_files_sha256_verified")
        || !json_bool(digest_gates, "wrapper_inputs_must_be_sha256_pinned")
    {
        anyhow::bail!("plugin install smoke digest gates are incomplete");
    }
    let dry_run = smoke
        .get("dry_run")
        .context("plugin install smoke missing dry_run")?;
    for field in [
        "provider_execution_started",
        "queue_mutated",
        "memory_written",
        "ao_artifacts_mutated",
        "release_approved",
        "control_plane_mutated",
    ] {
        if json_bool(dry_run, field) {
            anyhow::bail!("plugin install smoke dry_run field must be false: {field}");
        }
    }
    let observation = smoke
        .get("control_plane_observation")
        .context("plugin install smoke missing control_plane_observation")?;
    if json_string(observation, "role") != "read_only_observer"
        || json_bool(observation, "may_mutate_evidence")
        || json_bool(observation, "may_approve_release")
    {
        anyhow::bail!("plugin install smoke control-plane observation is not read-only");
    }
    Ok(())
}

fn validate_plugin_manifest_verification_contract(verification: &serde_json::Value) -> Result<()> {
    if json_string(verification, "schema_version") != "ao2.plugin-manifest-verification.v1" {
        anyhow::bail!(
            "plugin manifest verification requires ao2.plugin-manifest-verification.v1, got {}",
            json_string(verification, "schema_version")
        );
    }
    if json_string(verification, "status") != "passed" {
        anyhow::bail!("plugin manifest verification must be passed");
    }
    if !json_bool(verification, "file_digests_verified")
        || !json_bool(verification, "readiness_contract_verified")
        || !json_bool(verification, "wrapper_args_verified")
        || !json_bool(verification, "local_oauth_smokes_verified")
        || !json_bool(verification, "install_manifest_verified")
        || !json_bool(verification, "consumer_readme_verified")
        || !json_bool(verification, "token_safe_output_verified")
    {
        anyhow::bail!("plugin manifest verification is incomplete");
    }
    validate_plugin_provider_auth(
        verification
            .get("provider_auth")
            .context("plugin manifest verification missing provider_auth")?,
        "plugin manifest verification",
    )?;
    validate_plugin_observer_trust_boundary(
        verification
            .get("trust_boundary")
            .context("plugin manifest verification missing trust_boundary")?,
        "plugin manifest verification",
    )?;
    let observation = verification
        .get("control_plane_observation")
        .context("plugin manifest verification missing control_plane_observation")?;
    if json_string(observation, "role") != "read_only_observer"
        || json_bool(observation, "may_mutate_evidence")
        || json_bool(observation, "may_approve_release")
    {
        anyhow::bail!("plugin manifest verification control-plane observation is not read-only");
    }
    Ok(())
}

fn validate_plugin_manifest_contract(manifest: &serde_json::Value) -> Result<()> {
    if json_string(manifest, "schema_version") != "ao2.plugin-manifest.v1" {
        anyhow::bail!(
            "plugin manifest requires ao2.plugin-manifest.v1, got {}",
            json_string(manifest, "schema_version")
        );
    }
    if json_string(manifest, "status") != "packaged" {
        anyhow::bail!("plugin manifest must be packaged");
    }
    if manifest.get("plugin_targets") != Some(&serde_json::json!(["codex", "claude"])) {
        anyhow::bail!("plugin manifest must target codex and claude");
    }
    validate_plugin_provider_auth(
        manifest
            .get("provider_auth")
            .context("plugin manifest missing provider_auth")?,
        "plugin manifest",
    )?;
    validate_plugin_observer_trust_boundary(
        manifest
            .get("trust_boundary")
            .context("plugin manifest missing trust_boundary")?,
        "plugin manifest",
    )?;
    let digest_gates = manifest
        .get("digest_gates")
        .context("plugin manifest missing digest_gates")?;
    if !json_bool(digest_gates, "manifest_files_sha256_verified")
        || !json_bool(digest_gates, "wrapper_inputs_must_be_sha256_pinned")
    {
        anyhow::bail!("plugin manifest digest gates are incomplete");
    }
    let token_safe_output = manifest
        .get("token_safe_output")
        .context("plugin manifest missing token_safe_output")?;
    if json_string(token_safe_output, "redaction_policy") != "paths_status_and_digests_only"
        || json_bool(token_safe_output, "bearer_tokens_serialized")
        || json_bool(token_safe_output, "cookies_serialized")
        || json_bool(token_safe_output, "private_keys_serialized")
    {
        anyhow::bail!("plugin manifest token_safe_output is not safe");
    }
    Ok(())
}

fn plugin_manifest_named_file_path(
    manifest_dir: &Path,
    files: &serde_json::Map<String, serde_json::Value>,
    name: &str,
) -> Result<PathBuf> {
    let entry = files
        .get(name)
        .with_context(|| format!("plugin manifest files missing {name}"))?;
    plugin_manifest_package_file_path(manifest_dir, name, entry)
}

fn plugin_manifest_package_file_path(
    manifest_dir: &Path,
    name: &str,
    entry: &serde_json::Value,
) -> Result<PathBuf> {
    let relative_path = json_string(entry, "path");
    if relative_path.is_empty() {
        anyhow::bail!("plugin manifest file {name} missing path");
    }
    let path = PathBuf::from(&relative_path);
    if path.is_absolute()
        || path
            .components()
            .any(|component| matches!(component, std::path::Component::ParentDir))
    {
        anyhow::bail!("plugin manifest file {name} path must stay inside manifest dir");
    }
    let sha256 = json_string(entry, "sha256");
    if sha256.len() != 64 || !sha256.chars().all(|ch| ch.is_ascii_hexdigit()) {
        anyhow::bail!("plugin manifest file {name} sha256 must be a hex digest");
    }
    Ok(manifest_dir.join(path))
}

fn validate_plugin_local_oauth_smoke(smoke: &serde_json::Value, provider: &str) -> Result<()> {
    if json_string(smoke, "schema_version") != "ao2.plugin-local-oauth-smoke.v1" {
        anyhow::bail!(
            "plugin local OAuth smoke requires ao2.plugin-local-oauth-smoke.v1, got {}",
            json_string(smoke, "schema_version")
        );
    }
    if json_string(smoke, "provider") != provider {
        anyhow::bail!("plugin local OAuth smoke provider mismatch for {provider}");
    }
    let auth = smoke
        .get("auth")
        .context("plugin local OAuth smoke missing auth")?;
    if !json_bool(auth, "local_oauth_cli_only")
        || json_bool(auth, "provider_api_key_auth_allowed")
        || !json_bool(auth, "forbidden_provider_api_key_env_absent")
    {
        anyhow::bail!("plugin local OAuth smoke auth is not local OAuth CLI only");
    }
    validate_plugin_observer_trust_boundary(
        smoke
            .get("trust_boundary")
            .context("plugin local OAuth smoke missing trust_boundary")?,
        "plugin local OAuth smoke",
    )?;
    Ok(())
}

fn validate_plugin_install_manifest(install: &serde_json::Value) -> Result<()> {
    if json_string(install, "schema_version") != "ao2.codex-claude-plugin-install.v1" {
        anyhow::bail!(
            "plugin install manifest requires ao2.codex-claude-plugin-install.v1, got {}",
            json_string(install, "schema_version")
        );
    }
    if install.get("targets") != Some(&serde_json::json!(["codex", "claude"])) {
        anyhow::bail!("plugin install manifest must target codex and claude");
    }
    let commands = install
        .get("commands")
        .context("plugin install manifest missing commands")?;
    for command in [
        "readiness",
        "manifest_verify",
        "install_smoke",
        "package",
        "package_verify",
        "distribution_rehearsal",
        "consumer_lifecycle",
        "consumer_lifecycle_windows_recovery",
        "consumer_lifecycle_observer_bundle",
        "consumer_lifecycle_observer_bundle_verify",
        "control_plane_fixture_handoff",
        "control_plane_fixture_handoff_verify",
        "release_candidate",
        "release_candidate_verify",
        "release_candidate_windows_recovery",
        "release_candidate_windows_recovery_verify",
        "release_candidate_windows_transfer_bundle",
        "release_candidate_observer_bundle",
        "release_candidate_observer_bundle_verify",
        "release_candidate_control_plane_fixture_handoff",
        "release_candidate_control_plane_fixture_handoff_verify",
        "final_install_transcript",
        "final_install_transcript_observer_bundle",
        "closer_decision",
        "closer_decision_verify",
        "shipment_readiness",
        "distribution_observer_bundle",
        "clean_package_operator_index",
        "packaged_replacement_observer_bundle",
        "packaged_replacement_observer_bundle_verify",
        "adapter_scaffold",
        "adapter_scaffold_verify",
        "adapter_install_smoke",
        "adapter_install_smoke_verify",
        "adapter_install_smoke_observer_bundle",
        "adapter_observer_bundle",
        "wrapper_harness",
        "wrapper_harness_verify",
    ] {
        if json_string(commands, command).is_empty() {
            anyhow::bail!("plugin install manifest missing command {command}");
        }
    }
    validate_plugin_provider_auth(
        install
            .get("provider_auth")
            .context("plugin install manifest missing provider_auth")?,
        "plugin install manifest",
    )?;
    validate_plugin_observer_trust_boundary(
        install
            .get("trust_boundary")
            .context("plugin install manifest missing trust_boundary")?,
        "plugin install manifest",
    )?;
    Ok(())
}

