fn validate_plugin_manifest_consumer_readme(readme: &str) -> Result<()> {
    for required in [
        "ao2 plugin readiness --json",
        "ao2 plugin manifest-verify ",
        "ao2 plugin install-smoke ",
        "ao2 plugin package ",
        "ao2 plugin package-verify ",
        "ao2 plugin distribution-rehearsal ",
        "ao2 plugin consumer-lifecycle ",
        "ao2 plugin consumer-lifecycle-windows-recovery ",
        "ao2 plugin consumer-lifecycle-observer-bundle ",
        "ao2 plugin consumer-lifecycle-observer-bundle-verify ",
        "ao2 plugin control-plane-fixture-handoff ",
        "ao2 plugin control-plane-fixture-handoff-verify ",
        "ao2 plugin release-candidate ",
        "ao2 plugin release-candidate-verify ",
        "ao2 plugin release-candidate-windows-recovery ",
        "ao2 plugin release-candidate-windows-recovery-verify ",
        "ao2 plugin release-candidate-observer-bundle ",
        "ao2 plugin release-candidate-observer-bundle-verify ",
        "ao2 plugin release-candidate-control-plane-fixture-handoff ",
        "ao2 plugin release-candidate-control-plane-fixture-handoff-verify ",
        "ao2 plugin final-install-transcript ",
        "ao2 plugin final-install-transcript-observer-bundle ",
        "ao2 factory closer-decision ",
        "ao2 factory closer-decision-verify ",
        "ao2 plugin shipment-readiness ",
        "ao2 plugin distribution-observer-bundle ",
        "ao2 plugin clean-package-operator-index ",
        "ao2 plugin packaged-replacement-observer-bundle ",
        "ao2 plugin packaged-replacement-observer-bundle-verify ",
        "ao2 plugin adapter-scaffold ",
        "ao2 plugin adapter-scaffold-verify ",
        "ao2 plugin adapter-install-smoke ",
        "ao2 plugin adapter-install-smoke-verify ",
        "ao2 plugin adapter-install-smoke-observer-bundle ",
        "ao2 plugin adapter-observer-bundle ",
        "ao2 plugin wrapper-harness ",
        "ao2 plugin wrapper-harness-verify ",
        "local OAuth CLI only",
        "control_plane_role: read_only_observer",
        "mutates_ao_artifacts: false",
        "control_plane_approves_release: false",
    ] {
        if !readme.contains(required) {
            anyhow::bail!("plugin consumer README missing required text: {required}");
        }
    }
    for forbidden in [
        "Bearer ",
        "sk-",
        "OPENAI_API_KEY",
        "ANTHROPIC_API_KEY",
        "BEGIN PRIVATE KEY",
    ] {
        if readme.contains(forbidden) {
            anyhow::bail!("plugin consumer README contains forbidden marker: {forbidden}");
        }
    }
    Ok(())
}

fn validate_plugin_provider_auth(auth: &serde_json::Value, context: &str) -> Result<()> {
    if !json_bool(auth, "local_oauth_cli_only") || json_bool(auth, "provider_api_key_auth_allowed")
    {
        anyhow::bail!("{context} provider_auth is not local OAuth CLI only");
    }
    Ok(())
}

fn validate_plugin_observer_trust_boundary(
    trust_boundary: &serde_json::Value,
    context: &str,
) -> Result<()> {
    if json_string(trust_boundary, "execution_owner") != "ao2"
        || json_string(trust_boundary, "factory_v3_role") != "parity_auditor"
        || json_string(trust_boundary, "control_plane_role") != "read_only_observer"
        || json_bool(trust_boundary, "mutates_ao_artifacts")
        || json_bool(trust_boundary, "control_plane_approves_release")
    {
        anyhow::bail!("{context} trust_boundary is not observer-only");
    }
    Ok(())
}

fn plugin_wrapper_harness(options: PluginWrapperHarnessOptions) -> Result<()> {
    fail_if_provider_api_key_env_present()?;

    let supplied_readiness_sha256 = options.readiness_sha256.trim();
    let actual_readiness_sha256 = sha256_file(&options.readiness)?;
    if supplied_readiness_sha256 != actual_readiness_sha256 {
        anyhow::bail!(
            "readiness_sha256 mismatch for {}: expected {}, actual {}",
            options.readiness.display(),
            supplied_readiness_sha256,
            actual_readiness_sha256
        );
    }
    let readiness: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(&options.readiness)
            .with_context(|| format!("read {}", options.readiness.display()))?,
    )
    .with_context(|| format!("parse {}", options.readiness.display()))?;
    validate_plugin_readiness_contract(&readiness)?;

    let supplied_args_sha256 = options.args_sha256.trim();
    let actual_args_sha256 = sha256_file(&options.args_file)?;
    if supplied_args_sha256 != actual_args_sha256 {
        anyhow::bail!(
            "args_sha256 mismatch for {}: expected {}, actual {}",
            options.args_file.display(),
            supplied_args_sha256,
            actual_args_sha256
        );
    }
    let args_payload: PluginWrapperArgsFile = serde_json::from_str(
        &fs::read_to_string(&options.args_file)
            .with_context(|| format!("read {}", options.args_file.display()))?,
    )
    .with_context(|| format!("parse {}", options.args_file.display()))?;
    validate_plugin_wrapper_args(&args_payload, &options.run_kind)?;
    let resolved_args =
        plugin_wrapper_args_resolve_relative_paths(&options.args_file, &args_payload.args);

    fs::create_dir_all(&options.out_dir)
        .with_context(|| format!("create {}", options.out_dir.display()))?;
    let output =
        ProcessCommand::new(std::env::current_exe().context("resolve current ao2 binary")?)
            .args(&resolved_args)
            .env_remove("OPENAI_API_KEY")
            .env_remove("ANTHROPIC_API_KEY")
            .output()
            .context("run digest-pinned ao2 factory command")?;

    let stdout_raw = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr_raw = String::from_utf8_lossy(&output.stderr).to_string();
    let stdout_redacted = redact_secrets(&stdout_raw);
    let stderr_redacted = redact_secrets(&stderr_raw);
    let stdout_path = options.out_dir.join("stdout.redacted.txt");
    let stderr_path = options.out_dir.join("stderr.redacted.txt");
    atomic_write_text(&stdout_path, &stdout_redacted)?;
    atomic_write_text(&stderr_path, &stderr_redacted)?;

    let child_json = serde_json::from_str::<serde_json::Value>(&stdout_redacted).ok();
    let child_exit_code = output.status.code().unwrap_or(1);
    let status = if output.status.success() {
        "accepted"
    } else {
        "failed"
    };
    let redaction_counts = secret_redaction_class_counts(&format!("{stdout_raw}\n{stderr_raw}"));
    let ao2_artifacts = child_json
        .as_ref()
        .and_then(|json| json.get("artifacts"))
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));

    let summary_path = options.out_dir.join("plugin-wrapper-harness.json");
    let summary = serde_json::json!({
        "schema_version": "ao2.plugin-wrapper-harness.v1",
        "status": status,
        "run_kind": options.run_kind,
        "readiness_path": options.readiness.display().to_string(),
        "readiness_sha256": actual_readiness_sha256,
        "args_file": options.args_file.display().to_string(),
        "args_sha256": actual_args_sha256,
        "child_exit_code": child_exit_code,
        "exit_code_contract": {
            "success": 0,
            "runtime_error": 1,
            "cli_usage": 2,
            "enforced": true
        },
        "digest_gates": {
            "readiness_sha256_verified": true,
            "args_sha256_verified": true,
            "factory_command_digest_pinned_before_execution": true
        },
        "provider_auth": {
            "local_oauth_cli_only": true,
            "provider_api_key_auth_allowed": false,
            "forbidden_provider_api_key_env_absent": true
        },
        "trust_boundary": {
            "execution_owner": "ao2",
            "factory_v3_role": "parity_auditor",
            "control_plane_role": "read_only_observer",
            "mutates_ao_artifacts": false,
            "control_plane_approves_release": false
        },
        "token_safe_output": {
            "stdout_redacted": true,
            "stderr_redacted": true,
            "redaction_class_counts": redaction_counts
        },
        "evidence": {
            "bundle_path": options.out_dir.display().to_string(),
            "summary": summary_path.display().to_string(),
            "stdout_redacted": stdout_path.display().to_string(),
            "stderr_redacted": stderr_path.display().to_string()
        },
        "ao2_artifacts": ao2_artifacts,
        "control_plane_observation": {
            "role": "read_only_observer",
            "may_observe_evidence_bundle_path": true,
            "may_mutate_evidence": false,
            "may_approve_release": false
        }
    });
    let summary_body = serde_json::to_string_pretty(&summary)?;
    atomic_write_text(&summary_path, &summary_body)?;

    if options.json_output {
        println!("{summary_body}");
    } else {
        println!("status={status}");
        println!("schema_version=ao2.plugin-wrapper-harness.v1");
        println!("evidence_bundle_path={}", options.out_dir.display());
    }

    if output.status.success() {
        Ok(())
    } else {
        anyhow::bail!("digest-pinned ao2 factory command failed with exit code {child_exit_code}");
    }
}

fn plugin_wrapper_harness_verify(options: PluginWrapperHarnessVerifyOptions) -> Result<()> {
    fail_if_provider_api_key_env_present()?;

    let summary_path = options.evidence_dir.join("plugin-wrapper-harness.json");
    let supplied_summary_sha256 = options.summary_sha256.trim();
    let actual_summary_sha256 = sha256_file(&summary_path)?;
    if supplied_summary_sha256 != actual_summary_sha256 {
        anyhow::bail!(
            "plugin wrapper harness summary_sha256 mismatch for {}: expected {}, actual {}",
            summary_path.display(),
            supplied_summary_sha256,
            actual_summary_sha256
        );
    }

    let summary: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(&summary_path)
            .with_context(|| format!("read {}", summary_path.display()))?,
    )
    .with_context(|| format!("parse {}", summary_path.display()))?;
    validate_plugin_wrapper_harness_summary(&summary, &summary_path)?;

    let run_kind = json_string(&summary, "run_kind");
    let evidence = summary
        .get("evidence")
        .context("plugin wrapper harness summary missing evidence")?;
    let stdout_path = PathBuf::from(json_string(evidence, "stdout_redacted"));
    let stderr_path = PathBuf::from(json_string(evidence, "stderr_redacted"));
    factory_app_run_bundle_reject_secret_markers(&summary_path, "plugin-wrapper-harness.json")?;
    factory_app_run_bundle_reject_secret_markers(&stdout_path, "stdout.redacted.txt")?;
    factory_app_run_bundle_reject_secret_markers(&stderr_path, "stderr.redacted.txt")?;

    let artifact_count = summary
        .get("ao2_artifacts")
        .and_then(serde_json::Value::as_object)
        .map(|artifacts| artifacts.len())
        .unwrap_or_default();
    let verification = serde_json::json!({
        "schema_version": "ao2.plugin-wrapper-harness-verification.v1",
        "status": "passed",
        "evidence_dir": options.evidence_dir.display().to_string(),
        "summary_path": summary_path.display().to_string(),
        "summary_sha256": actual_summary_sha256,
        "run_kind": run_kind,
        "child_exit_code": json_u64(&summary, "child_exit_code"),
        "digest_gates_verified": true,
        "trust_boundary_verified": true,
        "token_safe_output_verified": true,
        "ao2_artifact_count": artifact_count,
        "control_plane_observation": {
            "role": "read_only_observer",
            "may_observe_evidence_bundle_path": true,
            "may_mutate_evidence": false,
            "may_approve_release": false
        },
        "factory_v3_role": "parity_auditor"
    });
    let body = serde_json::to_string_pretty(&verification)?;
    if options.json_output {
        println!("{body}");
    } else {
        println!("status=passed");
        println!("schema_version=ao2.plugin-wrapper-harness-verification.v1");
        println!("summary_sha256={actual_summary_sha256}");
    }
    Ok(())
}

fn validate_plugin_wrapper_harness_summary(
    summary: &serde_json::Value,
    summary_path: &Path,
) -> Result<()> {
    if json_string(summary, "schema_version") != "ao2.plugin-wrapper-harness.v1" {
        anyhow::bail!(
            "plugin wrapper harness summary requires ao2.plugin-wrapper-harness.v1, got {}",
            json_string(summary, "schema_version")
        );
    }
    if json_string(summary, "status") != "accepted" {
        anyhow::bail!("plugin wrapper harness summary must be accepted");
    }
    let run_kind = json_string(summary, "run_kind");
    if run_kind != "app-run" && run_kind != "project-run" {
        anyhow::bail!("plugin wrapper harness summary has unsupported run_kind: {run_kind}");
    }
    if json_u64(summary, "child_exit_code") != 0 {
        anyhow::bail!("plugin wrapper harness child_exit_code must be 0");
    }

    let exit_code_contract = summary
        .get("exit_code_contract")
        .context("plugin wrapper harness summary missing exit_code_contract")?;
    if json_u64(exit_code_contract, "success") != 0
        || json_u64(exit_code_contract, "runtime_error") != 1
        || json_u64(exit_code_contract, "cli_usage") != 2
        || !json_bool(exit_code_contract, "enforced")
    {
        anyhow::bail!("plugin wrapper harness exit_code_contract is not enforced");
    }

    let digest_gates = summary
        .get("digest_gates")
        .context("plugin wrapper harness summary missing digest_gates")?;
    if !json_bool(digest_gates, "readiness_sha256_verified")
        || !json_bool(digest_gates, "args_sha256_verified")
        || !json_bool(
            digest_gates,
            "factory_command_digest_pinned_before_execution",
        )
    {
        anyhow::bail!("plugin wrapper harness digest gates are incomplete");
    }

    let provider_auth = summary
        .get("provider_auth")
        .context("plugin wrapper harness summary missing provider_auth")?;
    if !json_bool(provider_auth, "local_oauth_cli_only")
        || json_bool(provider_auth, "provider_api_key_auth_allowed")
        || !json_bool(provider_auth, "forbidden_provider_api_key_env_absent")
    {
        anyhow::bail!("plugin wrapper harness provider_auth is not local OAuth CLI only");
    }

    let trust_boundary = summary
        .get("trust_boundary")
        .context("plugin wrapper harness summary missing trust_boundary")?;
    if json_string(trust_boundary, "execution_owner") != "ao2"
        || json_string(trust_boundary, "factory_v3_role") != "parity_auditor"
        || json_string(trust_boundary, "control_plane_role") != "read_only_observer"
        || json_bool(trust_boundary, "mutates_ao_artifacts")
        || json_bool(trust_boundary, "control_plane_approves_release")
    {
        anyhow::bail!("plugin wrapper harness trust_boundary is not observer-only");
    }

    let token_safe_output = summary
        .get("token_safe_output")
        .context("plugin wrapper harness summary missing token_safe_output")?;
    if !json_bool(token_safe_output, "stdout_redacted")
        || !json_bool(token_safe_output, "stderr_redacted")
    {
        anyhow::bail!("plugin wrapper harness token_safe_output is not redacted");
    }

    let evidence = summary
        .get("evidence")
        .context("plugin wrapper harness summary missing evidence")?;
    for field in ["summary", "stdout_redacted", "stderr_redacted"] {
        let path = PathBuf::from(json_string(evidence, field));
        if path.as_os_str().is_empty() {
            anyhow::bail!("plugin wrapper harness evidence missing {field}");
        }
        if field == "summary" && path != summary_path {
            anyhow::bail!("plugin wrapper harness summary path does not match evidence dir");
        }
        if !path.is_file() {
            anyhow::bail!(
                "plugin wrapper harness evidence file is missing for {field}: {}",
                path.display()
            );
        }
    }

    let control_plane_observation = summary
        .get("control_plane_observation")
        .context("plugin wrapper harness summary missing control_plane_observation")?;
    if json_string(control_plane_observation, "role") != "read_only_observer"
        || json_bool(control_plane_observation, "may_mutate_evidence")
        || json_bool(control_plane_observation, "may_approve_release")
    {
        anyhow::bail!("plugin wrapper harness control_plane_observation is not read-only");
    }

    if let Some(artifacts) = summary
        .get("ao2_artifacts")
        .and_then(serde_json::Value::as_object)
    {
        for (name, value) in artifacts {
            if value.is_null()
                && [
                    "acceptance_rubric",
                    "acceptance_rubric_sha256",
                    "project_plan",
                ]
                .contains(&name.as_str())
            {
                continue;
            }
            let Some(path) = value.as_str() else {
                anyhow::bail!("plugin wrapper harness ao2_artifacts.{name} must be a path string");
            };
            if name.ends_with("_sha256") {
                if path.len() != 64 || !path.chars().all(|ch| ch.is_ascii_hexdigit()) {
                    anyhow::bail!(
                        "plugin wrapper harness ao2_artifacts.{name} must be a sha256 hex digest"
                    );
                }
                continue;
            }
            if !Path::new(path).is_file() {
                anyhow::bail!(
                    "plugin wrapper harness ao2_artifacts.{name} file is missing: {path}"
                );
            }
        }
    }
    Ok(())
}

fn fail_if_provider_api_key_env_present() -> Result<()> {
    for key in ["OPENAI_API_KEY", "ANTHROPIC_API_KEY"] {
        if std::env::var_os(key).is_some() {
            anyhow::bail!("forbidden provider API key present in environment: {key}");
        }
    }
    Ok(())
}

fn validate_plugin_readiness_contract(readiness: &serde_json::Value) -> Result<()> {
    if json_string(readiness, "schema_version") != "ao2.plugin-readiness.v1" {
        anyhow::bail!(
            "plugin wrapper harness requires ao2.plugin-readiness.v1, got {}",
            json_string(readiness, "schema_version")
        );
    }
    if json_string(readiness, "status") != "accepted" {
        anyhow::bail!("plugin readiness artifact must be accepted");
    }
    let exit_codes = readiness
        .get("exit_codes")
        .context("plugin readiness missing exit_codes")?;
    if exit_codes
        .get("success")
        .and_then(serde_json::Value::as_u64)
        != Some(0)
        || exit_codes
            .get("runtime_error")
            .and_then(serde_json::Value::as_u64)
            != Some(1)
        || exit_codes
            .get("cli_usage")
            .and_then(serde_json::Value::as_u64)
            != Some(2)
    {
        anyhow::bail!("plugin readiness exit_codes must be success=0 runtime_error=1 cli_usage=2");
    }
    let trust_boundary = readiness
        .get("trust_boundary")
        .context("plugin readiness missing trust_boundary")?;
    if json_string(trust_boundary, "control_plane_role") != "read_only_observer"
        || trust_boundary
            .get("mutates_ao_artifacts")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
        || trust_boundary
            .get("control_plane_approves_release")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
    {
        anyhow::bail!("plugin readiness trust_boundary is not observer-only");
    }
    Ok(())
}

fn validate_plugin_wrapper_args(
    args_payload: &PluginWrapperArgsFile,
    run_kind: &str,
) -> Result<()> {
    if args_payload.schema_version != "ao2.plugin-wrapper-args.v1" {
        anyhow::bail!(
            "plugin wrapper args require ao2.plugin-wrapper-args.v1, got {}",
            args_payload.schema_version
        );
    }
    if args_payload.run_kind != run_kind {
        anyhow::bail!(
            "plugin wrapper run_kind mismatch: args file {}, CLI {}",
            args_payload.run_kind,
            run_kind
        );
    }
    let expected_subcommand = match run_kind {
        "app-run" => "app-run",
        "project-run" => "project-run",
        other => anyhow::bail!("unsupported plugin wrapper run_kind: {other}"),
    };
    if args_payload.args.len() < 2
        || args_payload.args[0] != "factory"
        || args_payload.args[1] != expected_subcommand
    {
        anyhow::bail!("plugin wrapper args must start with `factory {expected_subcommand}`");
    }
    for arg in &args_payload.args {
        let lowered = arg.to_ascii_lowercase();
        if lowered.contains("openai_api_key")
            || lowered.contains("anthropic_api_key")
            || lowered.contains("bearer ")
            || lowered.contains("--api-key")
        {
            anyhow::bail!("plugin wrapper args contain forbidden provider credential material");
        }
    }
    Ok(())
}

fn plugin_wrapper_args_resolve_relative_paths(args_file: &Path, args: &[String]) -> Vec<String> {
    let base = plugin_wrapper_args_path_base(args_file);
    let path_value_flags = [
        "--spec",
        "--target",
        "--provider-prompt-file",
        "--signing-key",
        "--out-dir",
        "--project-spec",
        "--project-plan",
        "--resume-from",
        "--app-run",
        "--factory-decision",
    ];
    let mut resolved = Vec::with_capacity(args.len());
    let mut index = 0usize;
    while index < args.len() {
        let arg = &args[index];
        if path_value_flags.contains(&arg.as_str()) && index + 1 < args.len() {
            resolved.push(arg.clone());
            resolved.push(plugin_wrapper_resolve_path_arg(&base, &args[index + 1]));
            index += 2;
            continue;
        }
        if let Some((flag, value)) = arg.split_once('=') {
            if path_value_flags.contains(&flag) {
                resolved.push(format!(
                    "{flag}={}",
                    plugin_wrapper_resolve_path_arg(&base, value)
                ));
                index += 1;
                continue;
            }
        }
        resolved.push(arg.clone());
        index += 1;
    }
    resolved
}

fn plugin_wrapper_args_path_base(args_file: &Path) -> PathBuf {
    let parent = args_file.parent().unwrap_or_else(|| Path::new("."));
    if parent
        .file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| name == "examples")
    {
        parent.parent().unwrap_or(parent).to_path_buf()
    } else {
        parent.to_path_buf()
    }
}

fn plugin_wrapper_resolve_path_arg(base: &Path, value: &str) -> String {
    let path = Path::new(value);
    if path.is_absolute() {
        value.to_string()
    } else {
        base.join(path).display().to_string()
    }
}

fn provider(command: ProviderCommand) -> Result<()> {
    match command {
        ProviderCommand::List => {
            for profile in provider_profiles() {
                println!(
                    "{}\t{}\t{}",
                    profile.name, profile.provider, profile.description
                );
            }
            Ok(())
        }
        ProviderCommand::Registry {
            control_plane_url,
            api_token,
            api_token_env,
            signing_key,
            signer_id,
            json,
        } => provider_registry(
            control_plane_url,
            api_token,
            api_token_env,
            signing_key,
            signer_id,
            json,
        ),
        ProviderCommand::Doctor { provider } => {
            let provider = parse_provider(&provider)?;
            let report = doctor_provider(provider)?;
            println!("{}", serde_json::to_string_pretty(&report)?);
            Ok(())
        }
        ProviderCommand::Matrix { json } => provider_matrix(json),
        ProviderCommand::Contract {
            provider,
            verify,
            require,
            json,
        } => provider_contract(provider, verify, require, json),
        ProviderCommand::SmokeAll {
            target,
            json,
            minimum_score,
            live_provider,
        } => provider_smoke_all(target, json, minimum_score, live_provider),
        ProviderCommand::Gate {
            target,
            require,
            minimum_score,
            json,
        } => provider_gate(target, require, minimum_score, json),
        ProviderCommand::Pilot {
            target,
            provider,
            template,
            run_id,
            provider_prompt_file,
            max_repair_attempts,
            provider_max_budget_usd,
            minimum_score,
            json,
        } => provider_pilot(ProviderPilotOptions {
            target,
            provider,
            template,
            run_id,
            provider_prompt_file,
            max_repair_attempts,
            max_budget_usd: provider_max_budget_usd,
            minimum_score,
            json,
        }),
        ProviderCommand::CostLedger {
            acceptance_root,
            json,
        } => provider_cost_ledger(acceptance_root, json),
        ProviderCommand::CostTrend {
            acceptance_root,
            json,
        } => provider_cost_trend(acceptance_root, json),
        ProviderCommand::Score {
            target,
            run_id,
            json,
        } => provider_score(target, run_id, json),
    }
}

fn provider_contract(
    provider: String,
    verify: bool,
    require: Vec<String>,
    json_output: bool,
) -> Result<()> {
    if verify {
        let required = if require.is_empty() {
            vec![provider]
        } else {
            require
        };
        let report = provider_contract_verify_json(&required);
        if json_output {
            println!("{}", serde_json::to_string_pretty(&report)?);
        } else {
            println!("schema={}", json_string(&report, "schema"));
            println!("status={}", json_string(&report, "status"));
            for reason in json_array(&report, "reasons") {
                println!(
                    "reason={}\tprovider={}\tmessage={}",
                    json_string(reason, "code"),
                    json_string(reason, "provider"),
                    json_string(reason, "message")
                );
            }
        }
        if json_string(&report, "status") != "verified" {
            anyhow::bail!("provider contract verification failed");
        }
        return Ok(());
    }

    let report = provider_contract_json(&provider)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("schema={}", json_string(&report, "schema"));
        println!("provider={}", json_string(&report, "provider"));
        println!("phase={}", json_string(&report, "phase"));
        println!(
            "execution_boundary={}",
            json_string(&report, "execution_boundary")
        );
        println!(
            "live_execution_guard_env={}",
            json_string(&report, "live_execution_guard_env")
        );
    }
    Ok(())
}

fn provider_contract_verify_json(required: &[String]) -> serde_json::Value {
    let required_providers = required
        .iter()
        .map(|provider| provider.trim().to_string())
        .filter(|provider| !provider.is_empty())
        .collect::<Vec<_>>();
    let required_providers = if required_providers.is_empty() {
        vec!["scripted".to_string()]
    } else {
        required_providers
    };
    let mut contracts = Vec::new();
    let mut reasons = Vec::new();

    for provider in &required_providers {
        if parse_provider(provider).is_err() {
            reasons.push(provider_contract_reason(
                "unknown_provider",
                provider,
                &format!("unknown provider: {provider}"),
            ));
            continue;
        }
        match provider_contract_json(provider) {
            Ok(contract) => {
                reasons.extend(provider_contract_verification_reasons(&contract));
                contracts.push(contract);
            }
            Err(error) => {
                reasons.push(provider_contract_reason(
                    "contract_unavailable",
                    provider,
                    &error.to_string(),
                ));
            }
        }
    }

    serde_json::json!({
        "schema": "ao2.provider-contract-verification.v1",
        "status": if reasons.is_empty() { "verified" } else { "failed" },
        "required_providers": required_providers,
        "contracts": contracts,
        "reasons": reasons
    })
}

fn provider_contract_verification_reasons(contract: &serde_json::Value) -> Vec<serde_json::Value> {
    let provider = json_string(contract, "provider");
    let mut reasons = Vec::new();
    if json_string(contract, "execution_boundary") != "sandbox_copy_then_digest_patch" {
        reasons.push(provider_contract_reason(
            "invalid_execution_boundary",
            &provider,
            "provider must execute in a sandbox copy before digest patch promotion",
        ));
    }
    if json_string(contract, "side_effect_boundary")
        != "target mutation only through exact digest patch apply"
    {
        reasons.push(provider_contract_reason(
            "invalid_side_effect_boundary",
            &provider,
            "provider target mutation must remain behind exact digest patch apply",
        ));
    }
    if matches!(provider.as_str(), "codex" | "claude" | "antigravity") {
        if json_string(contract, "phase") != "phase_1" {
            reasons.push(provider_contract_reason(
                "invalid_phase",
                &provider,
                "live provider contract must be phase_1",
            ));
        }
        if json_string(contract, "same_contract_as") != "scripted" {
            reasons.push(provider_contract_reason(
                "missing_scripted_contract_equivalence",
                &provider,
                "live provider contract must declare same_contract_as scripted",
            ));
        }
        if json_string(contract, "live_execution_guard_env").is_empty() {
            reasons.push(provider_contract_reason(
                "missing_live_guard",
                &provider,
                "live provider contract must declare a live execution guard env",
            ));
        }
    }
    if json_string(&contract["prompt_command"], "command").is_empty() {
        reasons.push(provider_contract_reason(
            "missing_prompt_command",
            &provider,
            "provider contract must include prompt command shape",
        ));
    }
    for invariant in [
        "provider cannot write target repo directly",
        "provider transcript is persisted as evidence",
        "sandbox diff preview emits exact action digest",
        "patch apply requires matching digest approval",
        "replay and closure remain runtime-owned",
    ] {
        if !json_array(contract, "policy_invariants")
            .iter()
            .any(|value| value.as_str() == Some(invariant))
            && !json_array(contract, "evidence_contract")
                .iter()
                .any(|value| value.as_str() == Some(invariant))
        {
            reasons.push(provider_contract_reason(
                "missing_contract_invariant",
                &provider,
                invariant,
            ));
        }
    }
    reasons
}

fn provider_contract_reason(code: &str, provider: &str, message: &str) -> serde_json::Value {
    serde_json::json!({
        "code": code,
        "provider": provider,
        "message": message
    })
}

fn provider_contract_json(provider: &str) -> Result<serde_json::Value> {
    let provider = provider.trim();
    let provider_kind = parse_provider(provider)?;
    let doctor = doctor_provider(provider_kind)?;
    let matrix = provider_matrix_json()?;
    let matrix_entry = json_array(&matrix, "providers")
        .iter()
        .find(|entry| json_string(entry, "provider") == provider)
        .cloned()
        .context("provider missing from readiness matrix")?;
    let prompt_command = build_provider_prompt_command(
        provider_kind,
        "AO2 provider contract probe. Do not modify files.",
        "contract-probe",
        Some(DEFAULT_PROVIDER_TIMEOUT_SECONDS * 1000),
        None,
    )?;
    let phase = match provider {
        "scripted" => "phase_0",
        "codex" | "claude" | "antigravity" => "phase_1",
        _ => "unknown",
    };
    let guard_env = provider_smoke_guard_env(provider).unwrap_or("");

    Ok(serde_json::json!({
        "schema": "ao2.provider-contract.v1",
        "provider": provider,
        "phase": phase,
        "same_contract_as": if provider == "scripted" { "" } else { "scripted" },
        "doctor": doctor,
        "execution_boundary": json_string(&matrix_entry, "execution_boundary"),
        "side_effect_boundary": json_string(&matrix_entry, "side_effect_boundary"),
        "timeout_seconds": json_u64(&matrix_entry, "timeout_seconds"),
        "live_execution_guard_env": guard_env,
        "prompt_command": {
            "role_id": prompt_command.role_id,
            "command": prompt_command.command.display().to_string(),
            "args": prompt_command.args,
            "working_dir": prompt_command.working_dir.display().to_string(),
            "timeout_seconds": prompt_command.timeout_ms.unwrap_or_default() / 1000
        },
        "transcript_fields": json_array(&matrix_entry, "transcript_fields"),
        "policy_invariants": json_array(&matrix_entry, "policy_invariants"),
        "evidence_contract": [
            "provider transcript is persisted as evidence",
            "sandbox diff preview emits exact action digest",
            "patch apply requires matching digest approval",
            "replay and closure remain runtime-owned"
        ]
    }))
}

fn provider_smoke_all(
    target: PathBuf,
    json_output: bool,
    minimum_score: u64,
    live_provider: Vec<String>,
) -> Result<()> {
    let report = provider_smoke_all_json(&target, minimum_score, &live_provider)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("schema={}", json_string(&report, "schema"));
        println!("minimum_score={}", json_u64(&report, "minimum_score"));
        for provider in json_array(&report, "providers") {
            println!(
                "{}\tavailable={}\tverdict={}\tscore={}",
                json_string(provider, "provider"),
                provider
                    .get("available")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(false),
                json_string(provider, "verdict"),
                json_u64(provider, "score")
            );
        }
    }
    Ok(())
}

fn provider_smoke_all_json(
    target: &Path,
    minimum_score: u64,
    live_providers: &[String],
) -> Result<serde_json::Value> {
    let live_provider_set = provider_smoke_live_provider_set(live_providers)?;
    let mut providers = Vec::new();
    for name in ["scripted", "codex", "claude", "antigravity"] {
        let provider = parse_provider(name)?;
        let doctor = doctor_provider(provider)?;
        let available = doctor.available;
        let should_run = name == "scripted" || live_provider_set.contains(name);
        if should_run && available {
            if let Some(guard_env) = provider_smoke_guard_env(name) {
                if std::env::var(guard_env).unwrap_or_default() != "1" {
                    providers.push(serde_json::json!({
                        "provider": name,
                        "available": available,
                        "doctor": doctor,
                        "run_id": "",
                        "score": 0,
                        "minimum_score": minimum_score,
                        "verdict": "guarded",
                        "guard_env": guard_env,
                        "scorecard": serde_json::Value::Null
                    }));
                    continue;
                }
            }
            providers.push(provider_smoke_run_json(
                target,
                name,
                provider,
                doctor,
                minimum_score,
            )?);
        } else {
            providers.push(serde_json::json!({
                "provider": name,
                "available": available,
                "doctor": doctor,
                "run_id": "",
                "score": 0,
                "minimum_score": minimum_score,
                "verdict": if available { "not_run" } else { "unavailable" },
                "scorecard": serde_json::Value::Null
            }));
        }
    }
    let mut report = serde_json::json!({
        "schema": "ao2.provider-smoke-all.v1",
        "target": target,
        "minimum_score": minimum_score,
        "live_providers": live_provider_set.iter().cloned().collect::<Vec<_>>(),
        "providers": providers
    });
    let history = record_provider_smoke_history(target, &report)?;
    report["history_path"] = serde_json::json!(provider_smoke_history_path(target));
    report["history_entry_count"] = serde_json::json!(json_u64(&history, "entry_count"));
    Ok(report)
}

fn provider_gate(
    target: PathBuf,
    require: Vec<String>,
    minimum_score: u64,
    json_output: bool,
) -> Result<()> {
    let report = provider_gate_json(&target, &require, minimum_score)?;
    if json_output {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("schema={}", json_string(&report, "schema"));
        println!("verdict={}", json_string(&report, "verdict"));
        println!("minimum_score={}", json_u64(&report, "minimum_score"));
        println!("history_path={}", json_string(&report, "history_path"));
        for provider in json_array(&report, "providers") {
            println!(
                "{}\tverdict={}\tscore={}",
                json_string(provider, "provider"),
                json_string(provider, "verdict"),
                json_u64(provider, "score")
            );
        }
        for reason in json_array(&report, "reasons") {
            println!(
                "reason={}\tprovider={}\tmessage={}",
                json_string(reason, "code"),
                json_string(reason, "provider"),
                json_string(reason, "message")
            );
        }
    }
    if json_string(&report, "verdict") != "ready" {
        anyhow::bail!("provider readiness gate not ready");
    }
    Ok(())
}

fn provider_gate_json(
    target: &Path,
    require: &[String],
    minimum_score: u64,
) -> Result<serde_json::Value> {
    let required_providers = provider_gate_required_providers(require)?;
    let history = read_provider_smoke_history(target)?;
    let latest = &history["latest"];
    let mut provider_entries = Vec::new();
    let mut reasons = Vec::new();

    if latest.is_null() || json_array(&history, "entries").is_empty() {
        reasons.push(provider_gate_reason(
            "missing_history",
            "",
            &format!(
                "No provider smoke history found at {}",
                provider_smoke_history_path(target).display()
            ),
        ));
    }

    for required in &required_providers {
        let provider = json_array(latest, "providers")
            .iter()
            .find(|provider| json_string(provider, "provider") == *required)
            .cloned();
        let Some(provider) = provider else {
            provider_entries.push(serde_json::json!({
                "provider": required,
                "verdict": "missing",
                "score": 0_u64,
                "minimum_score": minimum_score
            }));
            reasons.push(provider_gate_reason(
                "provider_missing",
                required,
                &format!("Required provider {required} is missing from latest smoke history"),
            ));
            continue;
        };

        let score = json_u64(&provider, "score");
        let verdict = json_string(&provider, "verdict");
        provider_entries.push(serde_json::json!({
            "provider": required,
            "verdict": verdict,
            "score": score,
            "minimum_score": minimum_score,
            "run_id": json_string(&provider, "run_id"),
            "guard_env": json_string(&provider, "guard_env")
        }));
        if verdict != "ready" {
            reasons.push(provider_gate_reason(
                "provider_not_ready",
                required,
                &format!("Required provider {required} has verdict {verdict}"),
            ));
        }
        if score < minimum_score {
            reasons.push(provider_gate_reason(
                "score_below_minimum",
                required,
                &format!(
                    "Required provider {required} score {score} is below minimum {minimum_score}"
                ),
            ));
        }
    }

    let verdict = if reasons.is_empty() {
        "ready"
    } else {
        "not_ready"
    };
    Ok(serde_json::json!({
        "schema": "ao2.provider-readiness-gate.v1",
        "target": target,
        "history_path": provider_smoke_history_path(target),
        "history_entry_count": json_u64(&history, "entry_count"),
        "minimum_score": minimum_score,
        "required_providers": required_providers,
        "verdict": verdict,
        "providers": provider_entries,
        "reasons": reasons
    }))
}

struct ProviderPilotOptions {
    target: PathBuf,
    provider: String,
    template: String,
    run_id: Option<String>,
    provider_prompt_file: PathBuf,
    max_repair_attempts: usize,
    max_budget_usd: Option<f64>,
    minimum_score: u64,
    json: bool,
}

fn provider_pilot_readiness_recovery(
    target: &Path,
    provider: &str,
    minimum_score: u64,
) -> serde_json::Value {
    let smoke_command = vec![
        "ao2".to_string(),
        "provider".to_string(),
        "smoke-all".to_string(),
        "--target".to_string(),
        target.display().to_string(),
        "--live-provider".to_string(),
        provider.to_string(),
        "--minimum-score".to_string(),
        minimum_score.to_string(),
        "--json".to_string(),
    ];
    let guard_env = provider_smoke_guard_env(provider).unwrap_or("");
    let posix_shell_command = if guard_env.is_empty() {
        smoke_command
            .iter()
            .map(|part| shell_quote(part))
            .collect::<Vec<_>>()
            .join(" ")
    } else {
        let mut shell_parts = vec![format!("{guard_env}=1")];
        shell_parts.extend(smoke_command.iter().map(|part| shell_quote(part)));
        shell_parts.join(" ")
    };
    let powershell_command = if guard_env.is_empty() {
        smoke_command
            .iter()
            .map(|part| powershell_quote(part))
            .collect::<Vec<_>>()
            .join(" ")
    } else {
        let mut shell_parts = vec![format!("$env:{guard_env}='1';")];
        shell_parts.extend(smoke_command.iter().map(|part| powershell_quote(part)));
        shell_parts.join(" ")
    };

    serde_json::json!({
        "schema": "ao2.provider-readiness-recovery.v1",
        "status": "blocked_until_live_smoke_passes",
        "provider": provider,
        "guard_env": guard_env,
        "minimum_score": minimum_score,
        "history_path": provider_smoke_history_path(target),
        "smoke_command": smoke_command,
        "smoke_shell_command": posix_shell_command,
        "smoke_posix_shell_command": posix_shell_command,
        "smoke_powershell_command": powershell_command,
        "next_action": "run the smoke_command with the guard_env set to 1, then re-run provider pilot"
    })
}

fn powershell_quote(input: &str) -> String {
    if input
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | '/' | ':' | '\\'))
    {
        input.to_string()
    } else {
        format!("'{}'", input.replace('\'', "''"))
    }
}

fn provider_pilot(options: ProviderPilotOptions) -> Result<()> {
    let report = provider_pilot_json(&options)?;
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("schema={}", json_string(&report, "schema"));
        println!("status={}", json_string(&report, "status"));
        println!("provider={}", json_string(&report, "provider"));
        println!("template={}", json_string(&report, "template"));
        println!("run_id={}", json_string(&report, "run_id"));
        println!("gate_verdict={}", json_string(&report["gate"], "verdict"));
        println!("shell_command={}", json_string(&report, "shell_command"));
    }
    if json_string(&report, "status") != "ready" {
        anyhow::bail!("provider pilot gate not ready");
    }
    Ok(())
}

fn provider_pilot_json(options: &ProviderPilotOptions) -> Result<serde_json::Value> {
    let target = &options.target;
    let provider = options.provider.trim();
    let template = options.template.as_str();
    let provider_prompt_file = &options.provider_prompt_file;
    let max_repair_attempts = options.max_repair_attempts;
    let max_budget_usd = options.max_budget_usd;
    let minimum_score = options.minimum_score;
    let run_id = options.run_id.clone();

    parse_provider(provider)?;
    if provider == "scripted" {
        anyhow::bail!("provider pilot requires codex or claude");
    }
    if !provider_prompt_file.is_file() {
        anyhow::bail!(
            "provider prompt file does not exist: {}",
            provider_prompt_file.display()
        );
    }
    if !TASK_TEMPLATES
        .iter()
        .any(|candidate| candidate.name == template)
    {
        anyhow::bail!("unknown template: {template}");
    }

    let required = vec![provider.to_string()];
    let gate = provider_gate_json(target, &required, minimum_score)?;
    if json_string(&gate, "verdict") != "ready" {
        let readiness_recovery = provider_pilot_readiness_recovery(target, provider, minimum_score);
        return Ok(serde_json::json!({
            "schema": "ao2.provider-pilot-plan.v1",
            "status": "blocked",
            "mode": "command_preview",
            "provider": provider,
            "template": template,
            "run_id": run_id.unwrap_or_default(),
            "target": target,
            "workflow": "",
            "provider_prompt_file": provider_prompt_file,
            "max_repair_attempts": max_repair_attempts,
            "max_budget_usd": max_budget_usd,
            "minimum_score": minimum_score,
            "gate": gate,
            "readiness_recovery": readiness_recovery,
            "command": [],
            "shell_command": ""
        }));
    }

    let workflow = materialize_template_workflow(target, template)?;
    let run_id =
        run_id.unwrap_or_else(|| format!("provider-pilot-{provider}-{}", generate_api_token()));
    let mut command = vec![
        "ao2".to_string(),
        "run".to_string(),
        "--template".to_string(),
        template.to_string(),
        "--target".to_string(),
        target.display().to_string(),
        "--run-id".to_string(),
        run_id.clone(),
        "--provider".to_string(),
        provider.to_string(),
        "--provider-prompt-file".to_string(),
        provider_prompt_file.display().to_string(),
        "--max-repair-attempts".to_string(),
        max_repair_attempts.to_string(),
    ];
    if let Some(max_budget_usd) = max_budget_usd {
        command.push("--provider-max-budget-usd".to_string());
        command.push(format_budget_usd(max_budget_usd)?);
    }
    let shell_command = command
        .iter()
        .map(|part| shell_quote(part))
        .collect::<Vec<_>>()
        .join(" ");
    let approval_packet = provider_pilot_approval_packet(ProviderPilotApprovalInput {
        target,
        provider,
        template,
        run_id: &run_id,
        provider_prompt_file,
        max_repair_attempts,
        max_budget_usd,
        minimum_score,
        command: &command,
        shell_command: &shell_command,
    })?;

    Ok(serde_json::json!({
        "schema": "ao2.provider-pilot-plan.v1",
        "status": "ready",
        "mode": "command_preview",
        "provider": provider,
        "template": template,
        "run_id": run_id,
        "target": target,
        "workflow": workflow,
        "provider_prompt_file": provider_prompt_file,
        "max_repair_attempts": max_repair_attempts,
        "max_budget_usd": max_budget_usd,
        "minimum_score": minimum_score,
        "gate": gate,
        "command": command,
        "shell_command": shell_command,
        "approval_packet": approval_packet
    }))
}

struct ProviderPilotApprovalInput<'a> {
    target: &'a Path,
    provider: &'a str,
    template: &'a str,
    run_id: &'a str,
    provider_prompt_file: &'a Path,
    max_repair_attempts: usize,
    max_budget_usd: Option<f64>,
    minimum_score: u64,
    command: &'a [String],
    shell_command: &'a str,
}

fn provider_pilot_approval_packet(
    input: ProviderPilotApprovalInput<'_>,
) -> Result<serde_json::Value> {
    let explicit_live_env = provider_pilot_guard_env(input.provider).unwrap_or("");
    let digest_input = serde_json::json!({
        "schema_version": "ao2.provider-pilot-approval-digest.v1",
        "provider": input.provider,
        "template": input.template,
        "run_id": input.run_id,
        "target": input.target.display().to_string(),
        "provider_prompt_file": input.provider_prompt_file.display().to_string(),
        "max_repair_attempts": input.max_repair_attempts,
        "max_budget_usd": input.max_budget_usd,
        "minimum_score": input.minimum_score,
        "explicit_live_env": explicit_live_env,
        "command": input.command,
        "shell_command": input.shell_command
    });
    let action_digest = sha256_hex(serde_json::to_string(&digest_input)?.as_bytes());
    Ok(serde_json::json!({
        "schema_version": "ao2.provider-pilot-approval.v1",
        "status": "approval_required",
        "approval_mode": "exact_action_digest",
        "required_form_field": "approval_action_digest",
        "action_digest": action_digest,
        "provider": input.provider,
        "run_id": input.run_id,
        "template": input.template,
        "target": input.target.display().to_string(),
        "provider_prompt_file": input.provider_prompt_file.display().to_string(),
        "max_repair_attempts": input.max_repair_attempts,
        "max_budget_usd": input.max_budget_usd,
        "minimum_score": input.minimum_score,
        "explicit_live_env": explicit_live_env,
        "next_action": "submit approval_action_digest with the exact action_digest to start this provider pilot"
    }))
}

fn provider_gate_required_providers(require: &[String]) -> Result<Vec<String>> {
    let providers = if require.is_empty() {
        vec!["scripted".to_string()]
    } else {
        require
            .iter()
            .map(|provider| provider.trim().to_string())
            .filter(|provider| !provider.is_empty())
            .collect::<Vec<_>>()
    };
    let mut seen = BTreeSet::new();
    let mut required = Vec::new();
    for provider in providers {
        parse_provider(&provider)?;
        if seen.insert(provider.clone()) {
            required.push(provider);
        }
    }
    Ok(required)
}

fn provider_gate_reason(code: &str, provider: &str, message: &str) -> serde_json::Value {
    serde_json::json!({
        "code": code,
        "provider": provider,
        "message": message
    })
}

fn provider_smoke_live_provider_set(live_providers: &[String]) -> Result<BTreeSet<String>> {
    let mut set = BTreeSet::new();
    for provider in live_providers {
        let name = provider.trim();
        if name.is_empty() {
            continue;
        }
        parse_provider(name)?;
        if name == "scripted" {
            anyhow::bail!("scripted provider always runs; --live-provider is for codex, claude, or antigravity");
        }
        set.insert(name.to_string());
    }
    Ok(set)
}

fn provider_smoke_guard_env(provider: &str) -> Option<&'static str> {
    provider_guard_env(provider, ProviderGuardKind::Smoke)
}

fn provider_pilot_guard_env(provider: &str) -> Option<&'static str> {
    provider_guard_env(provider, ProviderGuardKind::Pilot)
}

enum ProviderGuardKind {
    Smoke,
    Pilot,
}

fn provider_guard_env(provider: &str, kind: ProviderGuardKind) -> Option<&'static str> {
    let provider = parse_provider(provider).ok()?;
    let metadata = provider_metadata(provider);
    let guard = match kind {
        ProviderGuardKind::Smoke => metadata.smoke_guard_env?,
        ProviderGuardKind::Pilot => metadata.pilot_guard_env?,
    };
    match guard.as_str() {
        "AO2_LIVE_CODEX_SMOKE" => Some("AO2_LIVE_CODEX_SMOKE"),
        "AO2_LIVE_CLAUDE_SMOKE" => Some("AO2_LIVE_CLAUDE_SMOKE"),
        "AO2_LIVE_ANTIGRAVITY_SMOKE" => Some("AO2_LIVE_ANTIGRAVITY_SMOKE"),
        "AO2_LIVE_CODEX_PILOT" => Some("AO2_LIVE_CODEX_PILOT"),
        "AO2_LIVE_CLAUDE_PILOT" => Some("AO2_LIVE_CLAUDE_PILOT"),
        "AO2_LIVE_ANTIGRAVITY_PILOT" => Some("AO2_LIVE_ANTIGRAVITY_PILOT"),
        _ => None,
    }
}

fn provider_smoke_run_json(
    target: &Path,
    name: &str,
    provider: ao2_adapters::ProviderKind,
    doctor: ao2_adapters::ProviderDoctorReport,
    minimum_score: u64,
) -> Result<serde_json::Value> {
    let run_id = format!("provider-smoke-{name}-{}", generate_api_token());
    let smoke_root = target.join(".ao2").join("provider-smoke").join(&run_id);
    let smoke_repo = smoke_root.join("repo");
    write_provider_smoke_fixture(&smoke_repo)?;
    let workflow = materialize_template_workflow(&smoke_repo, "bug-fix")?;
    let mut summary = run_risky_pr_with_provider_prompt(ProviderRunOptions {
        target_repo: smoke_repo.clone(),
        workflow_path: workflow,
        run_id: Some(run_id),
        provider,
        prompt: provider_smoke_script().to_string(),
        max_repair_attempts: 1,
        max_budget_usd: None,
        repair_source: None,
    })?;
    if summary.status == ao2_runtime::RunStatus::WaitingForApproval {
        if let Some(resumed) = approve_and_resume_persisted_sandbox_patches(
            &smoke_repo,
            &summary.run_id,
            "human:provider-smoke-operator",
        )? {
            summary = resumed;
        }
    }
    let scorecard = provider_score_json(&smoke_repo, &summary.run_id)?;
    let score = json_u64(&scorecard, "score");
    let verdict = if score >= minimum_score {
        "ready"
    } else {
        "fail"
    };
    Ok(serde_json::json!({
        "provider": name,
        "available": true,
        "doctor": doctor,
        "run_id": summary.run_id,
        "status": format!("{:?}", summary.status),
        "score": score,
        "minimum_score": minimum_score,
        "verdict": verdict,
        "scorecard": scorecard
    }))
}

fn provider_smoke_history_path(target: &Path) -> PathBuf {
    target
        .join(".ao2")
        .join("provider-smoke")
        .join("history.json")
}

fn read_provider_smoke_history(target: &Path) -> Result<serde_json::Value> {
    let path = provider_smoke_history_path(target);
    match fs::read_to_string(&path) {
        Ok(content) => {
            serde_json::from_str(&content).with_context(|| format!("parse {}", path.display()))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            Ok(provider_smoke_empty_history(target))
        }
        Err(error) => Err(error).with_context(|| format!("read {}", path.display())),
    }
}

fn provider_smoke_empty_history(target: &Path) -> serde_json::Value {
    serde_json::json!({
        "schema": "ao2.provider-smoke-history.v1",
        "target": target,
        "history_path": provider_smoke_history_path(target),
        "entry_count": 0_u64,
        "latest": serde_json::Value::Null,
        "entries": []
    })
}

fn record_provider_smoke_history(
    target: &Path,
    report: &serde_json::Value,
) -> Result<serde_json::Value> {
    let path = provider_smoke_history_path(target);
    let mut history = read_provider_smoke_history(target)?;
    let mut entries = json_array(&history, "entries").to_vec();
    entries.push(serde_json::json!({
        "generated_at_ms": now_unix_ms(),
        "report": report
    }));
    history = serde_json::json!({
        "schema": "ao2.provider-smoke-history.v1",
        "target": target,
        "history_path": path,
        "entry_count": entries.len(),
        "latest": report,
        "entries": entries
    });
    atomic_write_text(&path, &serde_json::to_string_pretty(&history)?)?;
    Ok(history)
}

fn write_provider_smoke_fixture(repo: &Path) -> Result<()> {
    fs::create_dir_all(repo.join("discount_service"))
        .with_context(|| format!("create {}", repo.join("discount_service").display()))?;
    fs::create_dir_all(repo.join("tests"))
        .with_context(|| format!("create {}", repo.join("tests").display()))?;
    fs::write(
        repo.join("discount_service").join("__init__.py"),
        "from .discounts import calculate_discount\n\n__all__ = [\"calculate_discount\"]\n",
    )?;
    fs::write(
        repo.join("discount_service").join("discounts.py"),
        "def calculate_discount(price: float, discount_rate: float) -> float:\n    return price * (1 - discount_rate)\n",
    )?;
    fs::write(
        repo.join("tests").join("test_discounts.py"),
        "from discount_service.discounts import calculate_discount\n\n\ndef test_calculates_discount_for_valid_values():\n    assert calculate_discount(100, 0.25) == 75\n",
    )?;
    fs::write(
        repo.join("pytest.py"),
        r#"import importlib.util
import pathlib
import sys
import traceback


def main():
    root = pathlib.Path.cwd()
    failures = []
    for test_file in sorted((root / "tests").glob("test_*.py")):
        spec = importlib.util.spec_from_file_location(test_file.stem, test_file)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        for name in sorted(dir(module)):
            if name.startswith("test_"):
                try:
                    getattr(module, name)()
                    print(f"PASS {test_file.name}::{name}")
                except Exception:
                    failures.append(f"{test_file.name}::{name}")
                    traceback.print_exc()
    if failures:
        print(f"FAILED {len(failures)} tests: {failures}")
        return 1
    print("all tests passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"#,
    )?;
    Ok(())
}

fn provider_smoke_script() -> &'static str {
    r#"cat > discount_service/discounts.py <<'PY'
def calculate_discount(price: float, discount_rate: float) -> float:
    if price < 0:
        raise ValueError("price must be non-negative")
    if discount_rate < 0 or discount_rate > 1:
        raise ValueError("discount_rate must be between 0 and 1")
    return price * (1 - discount_rate)
PY
printf 'Summary: provider smoke added validation around discount math\n'
printf 'Changed files: discount_service/discounts.py\n'
"#
}

