fn render_closures(html: &mut String, pack: &serde_json::Value) -> Result<()> {
    html.push_str("<section>\n<h2>Evaluator Closure Evidence</h2>\n<p class=\"muted\">Closure Reports</p>\n<table><thead><tr><th>Verdict</th><th>Acceptance Criteria</th><th>Unresolved Concerns</th><th>Blockers</th></tr></thead><tbody>\n");
    for closure in json_array(pack, "closures") {
        writeln!(
            html,
            "<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>",
            escape_html(&json_string(closure, "verdict")),
            escape_html(&string_array_text(json_array(
                closure,
                "acceptance_criteria_results"
            ))),
            escape_html(&string_array_text(json_array(
                closure,
                "unresolved_concerns"
            ))),
            escape_html(&string_array_text(json_array(closure, "blockers")))
        )?;
    }
    html.push_str("</tbody></table>\n</section>\n");
    Ok(())
}

fn render_repair_attempts(html: &mut String, pack: &serde_json::Value) -> Result<()> {
    html.push_str("<section>\n<h2>Repair Attempts</h2>\n");
    let attempts = json_array(pack, "repair_attempts");
    if attempts.is_empty() {
        html.push_str("<p class=\"muted\">No repair attempts were recorded.</p>\n");
    } else {
        html.push_str("<table><thead><tr><th>Attempt</th><th>Trigger</th><th>Status</th><th>Summary</th></tr></thead><tbody>\n");
        for attempt in attempts {
            writeln!(
                html,
                "<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>",
                escape_html(&json_string(attempt, "attempt")),
                escape_html(&json_string(attempt, "trigger")),
                escape_html(&json_string(attempt, "status")),
                escape_html(&json_string(attempt, "summary"))
            )?;
        }
        html.push_str("</tbody></table>\n");
    }
    html.push_str("</section>\n");
    Ok(())
}

fn render_replay(
    html: &mut String,
    replay: &ao2_runtime::ReplaySummary,
    replay_status: &str,
) -> Result<()> {
    write!(
        html,
        r#"<section>
<h2>Replay Evidence</h2>
<p class="muted">Replay Integrity</p>
<div class="summary-grid">
<div class="metric"><div class="label">Status</div><div class="value ok">Replay {status}</div></div>
<div class="metric"><div class="label">Events</div><div class="value">{events}</div></div>
<div class="metric"><div class="label">Artifacts</div><div class="value">{artifacts}</div></div>
<div class="metric"><div class="label">Digest Failures</div><div class="value">{failures}</div></div>
</div>
<p>{event_types}</p>
</section>
"#,
        status = escape_html(replay_status),
        events = replay.event_count,
        artifacts = replay.artifact_count,
        failures = replay.digest_failures.len(),
        event_types = pills_from_strings(&replay.event_types)
    )?;
    Ok(())
}

fn render_markers(html: &mut String, pack: &serde_json::Value) -> Result<()> {
    html.push_str("<section>\n<h2>Run Markers</h2>\n<p>");
    html.push_str(&pills(json_array(pack, "markers")));
    html.push_str("</p>\n</section>\n");
    Ok(())
}

fn json_array<'a>(value: &'a serde_json::Value, key: &str) -> &'a [serde_json::Value] {
    value
        .get(key)
        .and_then(serde_json::Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[])
}

fn json_string(value: &serde_json::Value, key: &str) -> String {
    match value.get(key) {
        Some(serde_json::Value::String(text)) => text.clone(),
        Some(serde_json::Value::Null) | None => String::new(),
        Some(other) => other.to_string(),
    }
}

fn read_json_file<T: DeserializeOwned>(path: &Path) -> Result<T> {
    let text = fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
    let json = text.strip_prefix('\u{feff}').unwrap_or(&text);
    serde_json::from_str(json).with_context(|| format!("parse {}", path.display()))
}

fn json_bool(value: &serde_json::Value, key: &str) -> bool {
    value
        .get(key)
        .and_then(serde_json::Value::as_bool)
        .unwrap_or_default()
}

fn json_u64(value: &serde_json::Value, key: &str) -> u64 {
    value
        .get(key)
        .and_then(serde_json::Value::as_u64)
        .unwrap_or_default()
}

fn json_f64(value: &serde_json::Value, key: &str) -> f64 {
    value
        .get(key)
        .and_then(serde_json::Value::as_f64)
        .unwrap_or_default()
}

fn string_array_text(values: &[serde_json::Value]) -> String {
    values
        .iter()
        .map(json_value_text)
        .collect::<Vec<_>>()
        .join("; ")
}

fn concerns_text(values: &[serde_json::Value]) -> String {
    values
        .iter()
        .map(|value| {
            if value.is_object() {
                let severity = json_string(value, "severity");
                let message = json_string(value, "message");
                if severity.is_empty() {
                    message
                } else {
                    format!("{severity}: {message}")
                }
            } else {
                json_value_text(value)
            }
        })
        .collect::<Vec<_>>()
        .join("; ")
}

fn usage_text(value: Option<&serde_json::Value>) -> String {
    let Some(value) = value else {
        return String::new();
    };
    let mut parts = Vec::new();
    for key in ["input_tokens", "output_tokens", "total_tokens", "cost_usd"] {
        if let Some(metric) = value.get(key) {
            if !metric.is_null() {
                parts.push(format!("{key}: {}", json_value_text(metric)));
            }
        }
    }
    parts.join(", ")
}

fn pills(values: &[serde_json::Value]) -> String {
    values
        .iter()
        .map(json_value_text)
        .map(|text| format!("<span class=\"pill\">{}</span>", escape_html(&text)))
        .collect::<Vec<_>>()
        .join("")
}

fn pills_from_strings(values: &[String]) -> String {
    values
        .iter()
        .map(|text| format!("<span class=\"pill\">{}</span>", escape_html(text)))
        .collect::<Vec<_>>()
        .join("")
}

fn json_value_text(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::String(text) => text.clone(),
        serde_json::Value::Null => String::new(),
        other => other.to_string(),
    }
}

fn escape_html(input: &str) -> String {
    let mut escaped = String::with_capacity(input.len());
    for ch in input.chars() {
        match ch {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            '"' => escaped.push_str("&quot;"),
            '\'' => escaped.push_str("&#39;"),
            _ => escaped.push(ch),
        }
    }
    escaped
}

fn adapter(command: AdapterCommand) -> Result<()> {
    match command {
        AdapterCommand::Doctor { provider } => {
            let provider = parse_provider(&provider)?;
            let report = doctor_provider(provider)?;
            println!("{}", serde_json::to_string_pretty(&report)?);
            Ok(())
        }
        AdapterCommand::Run {
            provider,
            target,
            command,
            args,
            role_id,
            keep_sandbox,
            timeout_seconds,
        } => {
            let provider = parse_provider(&provider)?;
            let adapter = LocalCliAdapter::new(provider);
            let result = adapter.run_in_sandbox(SandboxRunRequest {
                target_repo: target,
                keep_sandbox,
                request: AdapterRunRequest {
                    role_id,
                    command,
                    args: split_tab_args(&args),
                    working_dir: PathBuf::from("."),
                    stdin: None,
                    timeout_ms: Some(timeout_seconds * 1_000),
                },
            })?;
            println!("{}", serde_json::to_string_pretty(&result)?);
            Ok(())
        }
        AdapterCommand::Prompt {
            provider,
            target,
            prompt,
            prompt_file,
            role_id,
            keep_sandbox,
            timeout_seconds,
            max_budget_usd,
        } => {
            let provider = parse_provider(&provider)?;
            let prompt = read_prompt(prompt, prompt_file)?;
            let result = run_provider_prompt_in_sandbox(ProviderPromptRequest {
                provider,
                target_repo: target,
                prompt,
                role_id,
                keep_sandbox,
                timeout_ms: Some(timeout_seconds * 1_000),
                max_budget_usd,
            })?;
            println!("{}", serde_json::to_string_pretty(&result)?);
            Ok(())
        }
        AdapterCommand::Patch { command } => adapter_patch(command),
    }
}

fn read_prompt(prompt: Option<String>, prompt_file: Option<PathBuf>) -> Result<String> {
    match (prompt, prompt_file) {
        (Some(prompt), None) => Ok(prompt),
        (None, Some(path)) => {
            fs::read_to_string(&path).with_context(|| format!("read prompt {}", path.display()))
        }
        (Some(_), Some(_)) => anyhow::bail!("use either --prompt or --prompt-file, not both"),
        (None, None) => anyhow::bail!("--prompt or --prompt-file is required"),
    }
}

fn adapter_patch(command: AdapterPatchCommand) -> Result<()> {
    match command {
        AdapterPatchCommand::Preview { target, sandbox } => {
            let preview = preview_sandbox_patch(&target, &sandbox)?;
            println!("{}", serde_json::to_string_pretty(&preview)?);
            Ok(())
        }
        AdapterPatchCommand::Apply {
            target,
            sandbox,
            digest,
            approver,
        } => {
            let preview = preview_sandbox_patch(&target, &sandbox)?;
            let applied = apply_sandbox_patch(SandboxPatchApplyRequest {
                target_repo: target,
                sandbox_path: sandbox,
                expected_subject: preview.approval_subject,
                expected_digest: digest,
                approver,
            })?;
            println!("{}", serde_json::to_string_pretty(&applied)?);
            Ok(())
        }
    }
}

fn split_tab_args(args: &str) -> Vec<String> {
    if args.is_empty() {
        Vec::new()
    } else {
        args.split('\t').map(str::to_string).collect()
    }
}

fn export(target: PathBuf, run_id: String) -> Result<()> {
    let path = target
        .join(".ao2")
        .join("runs")
        .join(&run_id)
        .join("evidence-pack")
        .join("evidence-pack.json");
    if !path.exists() {
        anyhow::bail!("evidence pack not found: {}", path.display());
    }
    println!("{}", path.display());
    Ok(())
}

fn doctor(
    json: bool,
    install_dir: Option<PathBuf>,
    provenance_dir: PathBuf,
    release: Option<String>,
    release_asset_dir: Option<PathBuf>,
    release_repo: String,
) -> Result<()> {
    let report = doctor_report_json(
        install_dir,
        provenance_dir,
        release,
        release_asset_dir,
        release_repo,
    )?;
    let status = json_string(&report, "status");
    if json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("status={status}");
        println!("details={}", serde_json::to_string_pretty(&report)?);
    }
    Ok(())
}

fn doctor_report_json(
    install_dir: Option<PathBuf>,
    provenance_dir: PathBuf,
    release: Option<String>,
    release_asset_dir: Option<PathBuf>,
    release_repo: String,
) -> Result<serde_json::Value> {
    let target = runtime_target_label();
    let binary_name = binary_name_for_target(&target);
    let install_dir = install_dir.unwrap_or_else(default_install_dir);
    let installed_binary = install_dir.join(binary_name);
    let installed = installed_binary.is_file();
    let on_path = installed && is_binary_on_path(binary_name, &installed_binary);
    let install_verification_evidence =
        doctor_install_verification_evidence_json(&installed_binary);

    let release_public_key = provenance_dir.join("ao2-release-signing-public.pem");
    let provenance_json = provenance_dir.join("ao2-release-provenance.json");
    let provenance_signature = provenance_dir.join("ao2-release-provenance.json.sig");
    let provenance_verified = verify_release_provenance_signature(
        &provenance_json,
        &provenance_signature,
        &release_public_key,
    );
    let mut release_report = serde_json::json!({
        "checked": false,
        "provenance_dir": provenance_dir,
        "public_key": release_public_key,
        "provenance_json": provenance_json,
        "provenance_signature": provenance_signature,
        "provenance_verified": provenance_verified,
    });
    if let Some(release_tag) = release {
        release_report = doctor_release_report_json(
            release_tag,
            release_repo,
            release_asset_dir,
            &provenance_json,
            provenance_verified,
        );
    }

    let scripted = doctor_provider(parse_provider("scripted")?)?;
    let providers = serde_json::json!({
        "scripted": scripted,
    });
    let dependencies = serde_json::json!({
        "native_crypto": true,
        "curl": command_exists("curl"),
        "tar": command_exists("tar"),
        "gh": command_exists("gh"),
    });
    let dependencies_ok = ["native_crypto", "curl", "tar"]
        .into_iter()
        .all(|name| dependencies[name].as_bool().unwrap_or(false));
    let release_ok = !release_report["checked"].as_bool().unwrap_or(false)
        || (release_report["assets_available"]
            .as_bool()
            .unwrap_or(false)
            && release_report["provenance_verified"]
                .as_bool()
                .unwrap_or(false)
            && release_report["provenance_tag_matches"]
                .as_bool()
                .unwrap_or(false));
    let status = if installed
        && on_path
        && provenance_verified
        && scripted.available
        && dependencies_ok
        && release_ok
    {
        "ok"
    } else {
        "attention"
    };

    Ok(serde_json::json!({
        "schema_version": "ao2.doctor.v1",
        "status": status,
        "version": env!("CARGO_PKG_VERSION"),
        "target": target,
        "install": {
            "install_dir": install_dir,
            "binary": installed_binary,
            "installed": installed,
            "on_path": on_path,
            "verification_evidence": install_verification_evidence,
        },
        "release": release_report,
        "providers": providers,
        "dependencies": dependencies,
    }))
}

fn doctor_install_verification_evidence_json(installed_binary: &Path) -> serde_json::Value {
    let evidence_path = install_verification_evidence_path(installed_binary);
    if !evidence_path.is_file() {
        return serde_json::json!({
            "present": false,
            "status": "missing",
            "path": evidence_path,
        });
    }
    match read_json_file::<serde_json::Value>(&evidence_path) {
        Ok(evidence) => serde_json::json!({
            "present": true,
            "path": evidence_path,
            "schema_version": evidence["schema_version"],
            "status": evidence["status"],
            "install_status": evidence["install_status"],
            "version": evidence["version"],
            "target": evidence["target"],
            "signature_verified": evidence["signature_verified"],
            "offline_verification": evidence["offline_verification"],
        }),
        Err(error) => serde_json::json!({
            "present": true,
            "status": "invalid",
            "path": evidence_path,
            "error": error.to_string(),
        }),
    }
}

fn doctor_release_report_json(
    release_tag: String,
    release_repo: String,
    release_asset_dir: Option<PathBuf>,
    provenance_json: &Path,
    provenance_verified: bool,
) -> serde_json::Value {
    let version = release_tag.strip_prefix('v').unwrap_or(&release_tag);
    let expected_assets = expected_release_asset_names(version);
    let provenance_tag = fs::read_to_string(provenance_json)
        .ok()
        .and_then(|body| serde_json::from_str::<serde_json::Value>(&body).ok())
        .map(|json| json_string(&json, "release_tag"))
        .unwrap_or_default();
    let provenance_tag_matches = provenance_tag == release_tag;

    let mut report = serde_json::json!({
        "checked": true,
        "release_tag": release_tag,
        "release_repo": release_repo,
        "expected_assets": expected_assets,
        "provenance_verified": provenance_verified,
        "provenance_tag": provenance_tag,
        "provenance_tag_matches": provenance_tag_matches,
    });

    if let Some(asset_dir) = release_asset_dir {
        let present_assets = expected_assets
            .iter()
            .filter(|asset| asset_dir.join(asset).is_file())
            .cloned()
            .collect::<Vec<_>>();
        let missing_assets = expected_assets
            .iter()
            .filter(|asset| !asset_dir.join(asset).is_file())
            .cloned()
            .collect::<Vec<_>>();
        report["asset_source"] = serde_json::json!("directory");
        report["asset_dir"] = serde_json::json!(asset_dir);
        report["asset_count"] = serde_json::json!(present_assets.len());
        report["assets_available"] = serde_json::json!(missing_assets.is_empty());
        report["present_assets"] = serde_json::json!(present_assets);
        report["missing_assets"] = serde_json::json!(missing_assets);
        report["rollback"] = release_rollback_summary_json(&asset_dir);
        return report;
    }

    if !command_exists("gh") {
        report["asset_source"] = serde_json::json!("github");
        report["assets_available"] = serde_json::json!(false);
        report["asset_count"] = serde_json::json!(0);
        report["error"] = serde_json::json!("gh_not_available");
        return report;
    }

    let Some(tag) = report["release_tag"].as_str() else {
        report["assets_available"] = serde_json::json!(false);
        return report;
    };
    let Some(repo) = report["release_repo"].as_str() else {
        report["assets_available"] = serde_json::json!(false);
        return report;
    };
    let output = ProcessCommand::new("gh")
        .args([
            "release",
            "view",
            tag,
            "--repo",
            repo,
            "--json",
            "assets,isDraft,isPrerelease",
        ])
        .output();
    match output {
        Ok(output) if output.status.success() => {
            let json = serde_json::from_slice::<serde_json::Value>(&output.stdout)
                .unwrap_or_else(|_| serde_json::json!({}));
            let names = json["assets"]
                .as_array()
                .map(|assets| {
                    assets
                        .iter()
                        .filter_map(|asset| asset["name"].as_str().map(str::to_string))
                        .collect::<BTreeSet<_>>()
                })
                .unwrap_or_default();
            let missing_assets = expected_assets
                .iter()
                .filter(|asset| !names.contains(*asset))
                .cloned()
                .collect::<Vec<_>>();
            report["asset_source"] = serde_json::json!("github");
            report["asset_count"] = serde_json::json!(names.len());
            report["assets_available"] = serde_json::json!(missing_assets.is_empty());
            report["present_assets"] = serde_json::json!(names);
            report["missing_assets"] = serde_json::json!(missing_assets);
            report["is_draft"] = json["isDraft"].clone();
            report["is_prerelease"] = json["isPrerelease"].clone();
        }
        Ok(output) => {
            report["asset_source"] = serde_json::json!("github");
            report["assets_available"] = serde_json::json!(false);
            report["asset_count"] = serde_json::json!(0);
            report["error"] = serde_json::json!(String::from_utf8_lossy(&output.stderr).trim());
        }
        Err(error) => {
            report["asset_source"] = serde_json::json!("github");
            report["assets_available"] = serde_json::json!(false);
            report["asset_count"] = serde_json::json!(0);
            report["error"] = serde_json::json!(error.to_string());
        }
    }
    report
}

fn release_rollback_summary_json(asset_dir: &Path) -> serde_json::Value {
    let summary = asset_dir.join("release-rollback-summary.json");
    if !summary.is_file() {
        return serde_json::json!({
            "checked": false,
            "status": "missing",
            "summary_json": summary,
        });
    }

    match fs::read_to_string(&summary)
        .ok()
        .and_then(|body| serde_json::from_str::<serde_json::Value>(&body).ok())
    {
        Some(mut json) => {
            json["checked"] = serde_json::json!(true);
            json["summary_json"] = serde_json::json!(summary);
            json
        }
        None => serde_json::json!({
            "checked": false,
            "status": "invalid",
            "summary_json": summary,
        }),
    }
}

fn expected_release_asset_names(version: &str) -> Vec<String> {
    let mut names = Vec::new();
    for target in [
        "macos-aarch64",
        "linux-aarch64",
        "linux-x86_64",
        "windows-x86_64",
    ] {
        let archive = format!("ao2-{version}-{target}.tar.gz");
        names.push(archive.clone());
        names.push(format!("{archive}.sha256"));
        names.push(format!("{archive}.sig"));
    }
    names.push("ao2-release-provenance.json".to_string());
    names.push("ao2-release-provenance.json.sig".to_string());
    names.push("ao2-release-signing-public.pem".to_string());
    names
}

fn version(json: bool) -> Result<()> {
    let target = runtime_target_label();
    let git_commit = runtime_git_commit();
    if json {
        let version = serde_json::json!({
            "package": "ao2",
            "version": env!("CARGO_PKG_VERSION"),
            "target": target,
            "git_commit": git_commit,
            "build_profile": option_env!("PROFILE").unwrap_or("unknown"),
            "release_manifest_schema": "ao2.release-manifest.v1",
            "release_provenance_schema": "ao2.release-provenance.v1"
        });
        println!("{}", serde_json::to_string_pretty(&version)?);
    } else {
        println!("ao2 {}", env!("CARGO_PKG_VERSION"));
        println!("target={target}");
        println!("git_commit={git_commit}");
    }
    Ok(())
}

fn runtime_git_commit() -> String {
    if let Some(commit) = option_env!("AO2_GIT_COMMIT") {
        return commit.to_string();
    }
    ProcessCommand::new("git")
        .args(["rev-parse", "HEAD"])
        .output()
        .ok()
        .filter(|output| output.status.success())
        .and_then(|output| String::from_utf8(output.stdout).ok())
        .map(|commit| commit.trim().to_string())
        .filter(|commit| !commit.is_empty())
        .unwrap_or_else(|| "unknown".to_string())
}

fn install(command: InstallCommand) -> Result<()> {
    match command {
        InstallCommand::Update {
            archive,
            release_base_url,
            version,
            target_label,
            provenance_dir,
            install_dir,
        } => install_update(InstallUpdateOptions {
            archive,
            release_base_url,
            version,
            target_label,
            provenance_dir,
            install_dir,
        }),
        InstallCommand::Rollback {
            install_dir,
            target_label,
        } => rollback_install(install_dir, target_label),
    }
}

fn upgrade(command: UpgradeCommand) -> Result<()> {
    match command {
        UpgradeCommand::Check {
            release_file,
            release_url,
        } => upgrade_check(release_file, release_url),
        UpgradeCommand::Apply(options) => {
            let options = *options;
            upgrade_apply(UpgradeApplyOptions {
                release_file: options.release_file,
                release_url: options.release_url,
                github_release: options.github_release,
                repo: options.repo,
                asset_dir: options.asset_dir,
                release_base_url: options.release_base_url,
                download_dir: options.download_dir,
                provenance_dir: options.provenance_dir,
                install_dir: options.install_dir,
                target_label: options.target_label,
            })
        }
    }
}

struct InstallUpdateOptions {
    archive: Option<PathBuf>,
    release_base_url: Option<String>,
    version: String,
    target_label: Option<String>,
    provenance_dir: PathBuf,
    install_dir: Option<PathBuf>,
}

fn install_update(options: InstallUpdateOptions) -> Result<()> {
    let result = install_update_result(options)?;
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

fn install_update_result(options: InstallUpdateOptions) -> Result<serde_json::Value> {
    let target = options.target_label.unwrap_or_else(runtime_target_label);
    let binary_name = binary_name_for_target(&target);
    let archive = match options.archive {
        Some(archive) => archive,
        None => {
            let base_url = options
                .release_base_url
                .context("--archive or --release-base-url is required")?;
            download_release_assets(
                &base_url,
                &options.version,
                &target,
                &options.provenance_dir,
            )?
        }
    };
    verify_release_archive_signature(&archive, &options.provenance_dir)?;

    let work_dir = std::env::temp_dir().join(format!(
        "ao2-install-update-{}-{}",
        std::process::id(),
        chrono_like_timestamp()
    ));
    let extract_dir = work_dir.join("extract");
    fs::create_dir_all(&extract_dir)
        .with_context(|| format!("create {}", extract_dir.display()))?;
    extract_tar_gz(&archive, &extract_dir)?;

    let manifest_path = extract_dir.join("RELEASE-MANIFEST.json");
    let manifest_text = fs::read_to_string(&manifest_path)
        .with_context(|| format!("read {}", manifest_path.display()))?;
    let manifest: serde_json::Value = serde_json::from_str(&manifest_text)
        .with_context(|| format!("parse {}", manifest_path.display()))?;
    if manifest["schema_version"] != "ao2.release-manifest.v1" {
        anyhow::bail!("unexpected release manifest schema");
    }
    if manifest["binary"] != binary_name {
        anyhow::bail!("archive binary does not match target {target}");
    }
    let binary_path = manifest["binary_path"]
        .as_str()
        .context("release manifest missing binary_path")?;
    ensure_safe_release_archive_path(binary_path, "release manifest binary_path")?;
    let source_binary = extract_dir.join(binary_path);
    let expected_binary_sha = manifest["binary_sha256"]
        .as_str()
        .context("release manifest missing binary_sha256")?;
    let actual_binary_sha = sha256_file(&source_binary)?;
    if actual_binary_sha != expected_binary_sha {
        anyhow::bail!("packaged binary checksum mismatch");
    }
    let offline_verification =
        verify_release_archive_offline_contract(&extract_dir, &manifest, &target, binary_name)?;

    let install_dir = options.install_dir.unwrap_or_else(default_install_dir);
    fs::create_dir_all(&install_dir)
        .with_context(|| format!("create {}", install_dir.display()))?;
    let installed_binary = install_dir.join(binary_name);
    let rollback_binary = rollback_path_for_binary(&installed_binary);
    let rollback_created = if installed_binary.exists() {
        fs::copy(&installed_binary, &rollback_binary).with_context(|| {
            format!(
                "copy rollback {} to {}",
                installed_binary.display(),
                rollback_binary.display()
            )
        })?;
        true
    } else {
        false
    };
    fs::copy(&source_binary, &installed_binary).with_context(|| {
        format!(
            "copy {} to {}",
            source_binary.display(),
            installed_binary.display()
        )
    })?;
    make_executable(&installed_binary)?;

    let evidence_path = install_verification_evidence_path(&installed_binary);
    let evidence = serde_json::json!({
        "schema_version": "ao2.install-verification-evidence.v1",
        "status": "verified",
        "install_status": "installed",
        "version": manifest["version"],
        "target": target,
        "installed_binary": installed_binary,
        "rollback_binary": rollback_created.then_some(rollback_binary),
        "signature_verified": true,
        "offline_verification": offline_verification,
        "archive": archive
    });
    let mut evidence_text = serde_json::to_string_pretty(&evidence)?;
    evidence_text.push('\n');
    atomic_write_text(&evidence_path, &evidence_text)?;

    let _ = fs::remove_dir_all(&work_dir);
    let mut result = evidence;
    result["status"] = serde_json::json!("installed");
    result["install_verification_evidence"] = serde_json::json!(evidence_path);
    Ok(result)
}

fn install_verification_evidence_path(installed_binary: &Path) -> PathBuf {
    let file_name = installed_binary
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("ao2");
    installed_binary.with_file_name(format!("{file_name}.install-verification.json"))
}

fn verify_release_archive_offline_contract(
    extract_dir: &Path,
    manifest: &serde_json::Value,
    target: &str,
    binary_name: &str,
) -> Result<serde_json::Value> {
    let verification_report = manifest["verification_report"]
        .as_str()
        .context("release manifest missing release verification report")?;
    if verification_report != "RELEASE-VERIFICATION.json" {
        anyhow::bail!("release verification report must be RELEASE-VERIFICATION.json");
    }
    ensure_safe_release_archive_path(verification_report, "release verification report")?;
    let report_path = extract_dir.join(verification_report);
    let report_text = fs::read_to_string(&report_path)
        .with_context(|| format!("read release verification report {}", report_path.display()))?;
    let report: serde_json::Value = serde_json::from_str(&report_text).with_context(|| {
        format!(
            "parse release verification report {}",
            report_path.display()
        )
    })?;
    if report["schema_version"] != "ao2.release-archive-offline-verification.v1" {
        anyhow::bail!("unexpected release verification report schema");
    }
    if report["status"] != "packaged" {
        anyhow::bail!("release verification report status must be packaged");
    }
    if report["target"] != target {
        anyhow::bail!("release verification report target does not match install target");
    }
    if report["binary"] != binary_name {
        anyhow::bail!("release verification report binary does not match install target");
    }
    let binary_path = manifest["binary_path"]
        .as_str()
        .context("release manifest missing binary_path")?;
    if report["binary_path"] != binary_path {
        anyhow::bail!("release verification report binary_path does not match release manifest");
    }
    let manifest_checksum_file = manifest["checksum_file"]
        .as_str()
        .context("release manifest missing checksum_file")?;
    let report_checksum_file = report["checksum_file"]
        .as_str()
        .context("release verification report missing checksum_file")?;
    if manifest_checksum_file != "SHA256SUMS" || report_checksum_file != "SHA256SUMS" {
        anyhow::bail!("release archive checksum file must be SHA256SUMS");
    }
    let checksum_path = extract_dir.join("SHA256SUMS");
    let checksum_text = fs::read_to_string(&checksum_path).with_context(|| {
        format!(
            "read release archive checksum file {}",
            checksum_path.display()
        )
    })?;
    let checksum_manifest = parse_release_archive_sha256sums(&checksum_text)?;
    if checksum_manifest.is_empty() {
        anyhow::bail!("release archive SHA256SUMS must not be empty");
    }

    for (relative_path, expected_sha) in &checksum_manifest {
        ensure_safe_release_archive_path(relative_path, "release archive SHA256SUMS")?;
        let file_path = extract_dir.join(relative_path);
        if !file_path.is_file() {
            anyhow::bail!("SHA256SUMS references missing release archive file {relative_path}");
        }
        let actual_sha = sha256_file(&file_path)?;
        if actual_sha != *expected_sha {
            anyhow::bail!("release archive checksum mismatch for {relative_path}");
        }
    }

    let expected_binary_sha = manifest["binary_sha256"]
        .as_str()
        .context("release manifest missing binary_sha256")?;
    match checksum_manifest.get(binary_path) {
        Some(checksum_sha) if checksum_sha == expected_binary_sha => {}
        Some(_) => anyhow::bail!("release manifest binary checksum does not match SHA256SUMS"),
        None => anyhow::bail!("SHA256SUMS must include packaged binary {binary_path}"),
    }

    let coverage = report["checksum_coverage"]
        .as_array()
        .context("release verification report missing checksum_coverage")?;
    let mut coverage_paths = BTreeSet::new();
    for value in coverage {
        let relative_path = value
            .as_str()
            .context("release verification checksum_coverage entries must be strings")?;
        ensure_safe_release_archive_path(relative_path, "release verification checksum_coverage")?;
        coverage_paths.insert(relative_path.to_string());
        if !checksum_manifest.contains_key(relative_path) {
            anyhow::bail!("SHA256SUMS must include checksum coverage entry {relative_path}");
        }
    }

    for required in [
        binary_path,
        "RELEASE-MANIFEST.json",
        "RELEASE-VERIFICATION.json",
        "install.sh",
        "install.ps1",
        "verify-release.sh",
        "Verify-Release.ps1",
        "README.txt",
        "VERSION",
    ] {
        if !coverage_paths.contains(required) {
            anyhow::bail!("release verification checksum_coverage must include {required}");
        }
        if !checksum_manifest.contains_key(required) {
            anyhow::bail!("SHA256SUMS must include {required}");
        }
    }

    require_release_report_false(&report, "provider_api_keys_required")?;
    require_release_report_false(&report, "control_plane_approves_release")?;
    require_release_report_false(&report, "mutates_ao_artifacts")?;
    if report["release_acceptance_owner"] != "factory-v3 evaluator-closer" {
        anyhow::bail!("release acceptance owner must be factory-v3 evaluator-closer");
    }

    Ok(serde_json::json!({
        "schema_version": "ao2.release-archive-offline-verification.v1",
        "status": "verified",
        "checksum_file": "SHA256SUMS",
        "verification_report": verification_report,
        "checksum_coverage_verified": true,
        "provider_api_keys_required": false,
        "control_plane_approves_release": false,
        "mutates_ao_artifacts": false,
        "release_acceptance_owner": "factory-v3 evaluator-closer"
    }))
}

fn parse_release_archive_sha256sums(text: &str) -> Result<BTreeMap<String, String>> {
    let mut manifest = BTreeMap::new();
    for (index, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let mut parts = line.split_whitespace();
        let digest = parts
            .next()
            .with_context(|| format!("missing digest on SHA256SUMS line {}", index + 1))?;
        let relative_path = parts
            .next()
            .with_context(|| format!("missing path on SHA256SUMS line {}", index + 1))?;
        if parts.next().is_some() {
            anyhow::bail!("invalid SHA256SUMS line {}", index + 1);
        }
        if digest.len() != 64 || !digest.chars().all(|ch| ch.is_ascii_hexdigit()) {
            anyhow::bail!("invalid digest on SHA256SUMS line {}", index + 1);
        }
        ensure_safe_release_archive_path(relative_path, "release archive SHA256SUMS")?;
        if manifest
            .insert(relative_path.to_string(), digest.to_ascii_lowercase())
            .is_some()
        {
            anyhow::bail!("duplicate SHA256SUMS entry {relative_path}");
        }
    }
    Ok(manifest)
}

fn ensure_safe_release_archive_path(relative_path: &str, label: &str) -> Result<()> {
    if relative_path.trim().is_empty() {
        anyhow::bail!("{label} path must not be empty");
    }
    let path = Path::new(relative_path);
    if path.is_absolute() {
        anyhow::bail!("{label} contains an absolute or parent-directory path");
    }
    for component in path.components() {
        match component {
            std::path::Component::Normal(_) | std::path::Component::CurDir => {}
            std::path::Component::ParentDir
            | std::path::Component::RootDir
            | std::path::Component::Prefix(_) => {
                anyhow::bail!("{label} contains an absolute or parent-directory path");
            }
        }
    }
    Ok(())
}

fn require_release_report_false(report: &serde_json::Value, key: &str) -> Result<()> {
    match report.get(key).and_then(serde_json::Value::as_bool) {
        Some(false) => Ok(()),
        Some(true) => anyhow::bail!("release verification report {key} must be false"),
        None => anyhow::bail!("release verification report missing boolean {key}"),
    }
}

fn rollback_install(install_dir: Option<PathBuf>, target_label: Option<String>) -> Result<()> {
    let target = target_label.unwrap_or_else(runtime_target_label);
    let binary_name = binary_name_for_target(&target);
    let install_dir = install_dir.unwrap_or_else(default_install_dir);
    let installed_binary = install_dir.join(binary_name);
    let rollback_binary = rollback_path_for_binary(&installed_binary);
    if !rollback_binary.is_file() {
        anyhow::bail!("rollback binary not found: {}", rollback_binary.display());
    }
    fs::copy(&rollback_binary, &installed_binary).with_context(|| {
        format!(
            "copy rollback {} to {}",
            rollback_binary.display(),
            installed_binary.display()
        )
    })?;
    make_executable(&installed_binary)?;
    let result = serde_json::json!({
        "status": "rolled_back",
        "target": target,
        "installed_binary": installed_binary,
        "rollback_binary": rollback_binary,
    });
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

struct UpgradeApplyOptions {
    release_file: Option<PathBuf>,
    release_url: Option<String>,
    github_release: Option<String>,
    repo: String,
    asset_dir: Option<PathBuf>,
    release_base_url: Option<String>,
    download_dir: PathBuf,
    provenance_dir: Option<PathBuf>,
    install_dir: Option<PathBuf>,
    target_label: Option<String>,
}

fn upgrade_apply(options: UpgradeApplyOptions) -> Result<()> {
    let UpgradeApplyOptions {
        release_file,
        release_url,
        github_release,
        repo,
        mut asset_dir,
        release_base_url,
        download_dir,
        provenance_dir,
        install_dir,
        target_label,
    } = options;
    let release = if let Some(tag) = github_release {
        if release_file.is_some()
            || release_url.is_some()
            || asset_dir.is_some()
            || release_base_url.is_some()
        {
            anyhow::bail!(
                "--github-release cannot be combined with release metadata or asset source flags"
            );
        }
        download_github_release_assets(&repo, &tag, &download_dir)?;
        asset_dir = Some(download_dir.clone());
        release_metadata_from_asset_dir(&download_dir, &tag)?
    } else {
        read_release_metadata(release_file, release_url)?
    };
    let check = upgrade_check_report(&release)?;
    let latest_version = check["latest_version"]
        .as_str()
        .context("upgrade check missing latest_version")?
        .to_string();
    let target = target_label.unwrap_or_else(runtime_target_label);
    let archive_name = release_asset_name(&release, &target, &latest_version)
        .with_context(|| format!("release is missing archive asset for target {target}"))?;
    let provenance_dir = provenance_dir.unwrap_or_else(|| download_dir.join("provenance"));
    fs::create_dir_all(&download_dir)
        .with_context(|| format!("create {}", download_dir.display()))?;
    fs::create_dir_all(&provenance_dir)
        .with_context(|| format!("create {}", provenance_dir.display()))?;

    let archive = if let Some(asset_dir) = asset_dir {
        copy_release_asset(&asset_dir, &archive_name, &download_dir)?;
        for name in required_provenance_asset_names(&archive_name) {
            copy_release_asset(&asset_dir, &name, &provenance_dir)?;
        }
        download_dir.join(&archive_name)
    } else if let Some(base_url) = release_base_url {
        download_release_assets(&base_url, &latest_version, &target, &provenance_dir)?
    } else {
        download_release_asset_from_metadata(&release, &archive_name, &download_dir)?;
        for name in required_provenance_asset_names(&archive_name) {
            download_release_asset_from_metadata(&release, &name, &provenance_dir)?;
        }
        download_dir.join(&archive_name)
    };

    let install = install_update_result(InstallUpdateOptions {
        archive: Some(archive),
        release_base_url: None,
        version: latest_version,
        target_label: Some(target),
        provenance_dir,
        install_dir,
    })?;
    let result = serde_json::json!({
        "schema_version": "ao2.upgrade-apply.v1",
        "status": "upgraded",
        "check": check,
        "install": install,
    });
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

fn upgrade_check(release_file: Option<PathBuf>, release_url: Option<String>) -> Result<()> {
    let release = read_release_metadata(release_file, release_url)?;
    let result = upgrade_check_report(&release)?;
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

fn read_release_metadata(
    release_file: Option<PathBuf>,
    release_url: Option<String>,
) -> Result<serde_json::Value> {
    let release = match (release_file, release_url) {
        (Some(path), None) => fs::read_to_string(&path)
            .with_context(|| format!("read release metadata {}", path.display()))?,
        (None, Some(url)) => read_url(&url)?,
        (Some(_), Some(_)) => anyhow::bail!("use either --release-file or --release-url"),
        (None, None) => anyhow::bail!("--release-file or --release-url is required"),
    };
    serde_json::from_str(&release).context("parse release metadata json")
}

fn upgrade_check_report(release: &serde_json::Value) -> Result<serde_json::Value> {
    let latest_version = release_version(release).context("release metadata missing version")?;
    let current_version = env!("CARGO_PKG_VERSION");
    let update_available =
        compare_versions(&latest_version, current_version) == std::cmp::Ordering::Greater;
    let assets = release
        .get("assets")
        .cloned()
        .unwrap_or_else(|| serde_json::Value::Array(Vec::new()));
    let result = serde_json::json!({
        "schema_version": "ao2.upgrade-check.v1",
        "current_version": current_version,
        "latest_version": latest_version,
        "update_available": update_available,
        "assets": assets,
    });
    Ok(result)
}

fn release_asset_name(release: &serde_json::Value, target: &str, version: &str) -> Option<String> {
    let expected = format!("ao2-{version}-{target}.tar.gz");
    release
        .get("assets")
        .and_then(|assets| assets.as_array())
        .and_then(|assets| {
            assets
                .iter()
                .filter_map(release_asset_name_value)
                .find(|name| name == &expected)
                .or_else(|| {
                    assets
                        .iter()
                        .filter_map(release_asset_name_value)
                        .find(|name| name.contains(target) && name.ends_with(".tar.gz"))
                })
        })
}

fn release_asset_name_value(asset: &serde_json::Value) -> Option<String> {
    asset
        .get("name")
        .and_then(|name| name.as_str())
        .map(str::to_string)
}

fn required_provenance_asset_names(archive_name: &str) -> Vec<String> {
    vec![
        format!("{archive_name}.sha256"),
        format!("{archive_name}.sig"),
        "ao2-release-signing-public.pem".to_string(),
        "ao2-release-provenance.json".to_string(),
        "ao2-release-provenance.json.sig".to_string(),
    ]
}

fn copy_release_asset(asset_dir: &Path, name: &str, dest_dir: &Path) -> Result<()> {
    let source = asset_dir.join(name);
    let dest = dest_dir.join(name);
    if source == dest {
        return Ok(());
    }
    fs::copy(&source, &dest).with_context(|| {
        format!(
            "copy release asset {} to {}",
            source.display(),
            dest.display()
        )
    })?;
    Ok(())
}

fn download_release_asset_from_metadata(
    release: &serde_json::Value,
    name: &str,
    dest_dir: &Path,
) -> Result<()> {
    let url = release
        .get("assets")
        .and_then(|assets| assets.as_array())
        .and_then(|assets| {
            assets.iter().find_map(|asset| {
                let asset_name = asset.get("name")?.as_str()?;
                if asset_name != name {
                    return None;
                }
                asset
                    .get("browser_download_url")
                    .or_else(|| asset.get("url"))
                    .and_then(|url| url.as_str())
                    .map(str::to_string)
            })
        })
        .with_context(|| format!("release metadata missing downloadable asset {name}"))?;
    download_file(&url, &dest_dir.join(name))
}

fn download_github_release_assets(repo: &str, tag: &str, download_dir: &Path) -> Result<()> {
    fs::create_dir_all(download_dir)
        .with_context(|| format!("create {}", download_dir.display()))?;
    if let Some(fake_asset_dir) = std::env::var_os("AO2_TEST_FAKE_GH_ASSET_DIR") {
        let fake_asset_dir = PathBuf::from(fake_asset_dir);
        for entry in fs::read_dir(&fake_asset_dir)
            .with_context(|| format!("read {}", fake_asset_dir.display()))?
        {
            let entry = entry?;
            if entry.file_type()?.is_file() {
                fs::copy(entry.path(), download_dir.join(entry.file_name())).with_context(
                    || {
                        format!(
                            "copy fake gh asset {} to {}",
                            entry.path().display(),
                            download_dir.display()
                        )
                    },
                )?;
            }
        }
        return Ok(());
    }
    let status = ProcessCommand::new("gh")
        .args(["release", "download", tag, "--repo", repo, "--dir"])
        .arg(download_dir)
        .arg("--clobber")
        .status()
        .with_context(|| format!("run gh release download {tag} from {repo}"))?;
    if !status.success() {
        anyhow::bail!("gh release download failed for {repo} {tag}");
    }
    Ok(())
}

fn release_metadata_from_asset_dir(asset_dir: &Path, tag: &str) -> Result<serde_json::Value> {
    let mut assets = Vec::new();
    for entry in fs::read_dir(asset_dir).with_context(|| format!("read {}", asset_dir.display()))? {
        let entry = entry?;
        if entry.file_type()?.is_file() {
            let name = entry.file_name().to_string_lossy().to_string();
            assets.push(serde_json::json!({
                "name": name,
                "browser_download_url": entry.path().display().to_string(),
            }));
        }
    }
    assets.sort_by_key(|left| json_string(left, "name"));
    Ok(serde_json::json!({
        "tagName": tag,
        "assets": assets,
    }))
}

fn release_version(release: &serde_json::Value) -> Option<String> {
    release
        .get("tagName")
        .or_else(|| release.get("tag_name"))
        .or_else(|| release.get("name"))
        .and_then(|value| value.as_str())
        .map(|version| version.trim_start_matches('v').to_string())
}

fn read_url(url: &str) -> Result<String> {
    let output = ProcessCommand::new("curl")
        .args(["--fail", "--location", "--silent", "--show-error"])
        .arg(url)
        .output()
        .with_context(|| format!("run curl for {url}"))?;
    if !output.status.success() {
        anyhow::bail!("download failed: {url}");
    }
    String::from_utf8(output.stdout).context("release metadata is utf8")
}

fn compare_versions(left: &str, right: &str) -> std::cmp::Ordering {
    let left = parse_version_tuple(left);
    let right = parse_version_tuple(right);
    left.cmp(&right)
}

fn parse_version_tuple(version: &str) -> Vec<u64> {
    version
        .split(|ch: char| !ch.is_ascii_digit())
        .filter(|part| !part.is_empty())
        .map(|part| part.parse::<u64>().unwrap_or(0))
        .collect()
}

fn default_install_dir() -> PathBuf {
    if cfg!(windows) {
        std::env::var_os("LOCALAPPDATA")
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                std::env::var_os("USERPROFILE")
                    .map(PathBuf::from)
                    .unwrap_or_else(|| PathBuf::from("."))
            })
            .join("AO2")
            .join("bin")
    } else {
        std::env::var_os("HOME")
            .map(PathBuf::from)
            .unwrap_or_else(|| PathBuf::from("."))
            .join(".local")
            .join("bin")
    }
}

fn chrono_like_timestamp() -> String {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_nanos().to_string())
        .unwrap_or_else(|_| "0".to_string())
}

fn download_release_assets(
    base_url: &str,
    version: &str,
    target: &str,
    provenance_dir: &Path,
) -> Result<PathBuf> {
    fs::create_dir_all(provenance_dir)
        .with_context(|| format!("create {}", provenance_dir.display()))?;
    let archive_name = format!("ao2-{version}-{target}.tar.gz");
    let archive = provenance_dir.join(&archive_name);
    download_file(
        &format!("{}/{}", base_url.trim_end_matches('/'), archive_name),
        &archive,
    )?;
    for asset in [
        format!("{archive_name}.sha256"),
        format!("{archive_name}.sig"),
        "ao2-release-signing-public.pem".to_string(),
        "ao2-release-provenance.json".to_string(),
        "ao2-release-provenance.json.sig".to_string(),
    ] {
        download_file(
            &format!("{}/{}", base_url.trim_end_matches('/'), asset),
            &provenance_dir.join(asset),
        )?;
    }
    Ok(archive)
}

fn download_file(url: &str, dest: &Path) -> Result<()> {
    let status = ProcessCommand::new("curl")
        .args([
            "--fail",
            "--location",
            "--silent",
            "--show-error",
            "--output",
        ])
        .arg(dest)
        .arg(url)
        .status()
        .with_context(|| format!("run curl for {url}"))?;
    if !status.success() {
        anyhow::bail!("download failed: {url}");
    }
    Ok(())
}

fn verify_release_archive_signature(archive: &Path, provenance_dir: &Path) -> Result<()> {
    let archive_name = archive
        .file_name()
        .and_then(|name| name.to_str())
        .context("archive filename is utf8")?;
    let checksum_file = provenance_dir.join(format!("{archive_name}.sha256"));
    let signature_file = provenance_dir.join(format!("{archive_name}.sig"));
    let public_key = provenance_dir.join("ao2-release-signing-public.pem");
    if !checksum_file.is_file() {
        anyhow::bail!("missing release checksum: {}", checksum_file.display());
    }
    if !signature_file.is_file() {
        anyhow::bail!("missing release signature: {}", signature_file.display());
    }
    if !public_key.is_file() {
        anyhow::bail!("missing release public key: {}", public_key.display());
    }
    let checksum_text = fs::read_to_string(&checksum_file)
        .with_context(|| format!("read {}", checksum_file.display()))?;
    let expected = checksum_text
        .lines()
        .find_map(|line| {
            let mut parts = line.split_whitespace();
            let digest = parts.next()?;
            let name = parts.next()?;
            (name == archive_name).then(|| digest.to_string())
        })
        .with_context(|| format!("checksum for {archive_name} not found"))?;
    let actual = sha256_file(archive)?;
    if actual != expected {
        anyhow::bail!("archive checksum mismatch");
    }
    let verified = verify_file_signature(archive, &signature_file, &public_key)?;
    if !verified {
        anyhow::bail!("archive signature verification failed");
    }
    Ok(())
}

fn derive_public_key_from_private_key(private_key: &Path, public_key: &Path) -> Result<()> {
    if let Some(parent) = public_key.parent() {
        fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
    }
    let public_pem = public_key_pem_from_private_key(private_key)?;
    atomic_write_text(public_key, &public_pem)?;
    Ok(())
}

fn public_key_pem_from_private_key(private_key: &Path) -> Result<String> {
    let private_key = read_rsa_private_key(private_key)?;
    RsaPublicKey::from(&private_key)
        .to_public_key_pem(LineEnding::LF)
        .context("encode RSA public key pem")
}

fn sign_file_with_private_key(private_key: &Path, input: &Path, signature: &Path) -> Result<()> {
    let input_bytes = fs::read(input).with_context(|| format!("read {}", input.display()))?;
    let signature_bytes = sign_bytes_with_private_key(private_key, &input_bytes)?;
    if let Some(parent) = signature.parent() {
        fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
    }
    fs::write(signature, signature_bytes)
        .with_context(|| format!("write {}", signature.display()))?;
    Ok(())
}

fn sign_bytes_with_private_key(private_key: &Path, input_bytes: &[u8]) -> Result<Vec<u8>> {
    let private_key = read_rsa_private_key(private_key)?;
    let signing_key = SigningKey::<Sha256>::new(private_key);
    let signed: RsaPkcs1v15Signature = signing_key.sign(input_bytes);
    Ok(signed.to_bytes().to_vec())
}

fn verify_file_signature(input: &Path, signature: &Path, public_key: &Path) -> Result<bool> {
    if !input.is_file() || !signature.is_file() || !public_key.is_file() {
        return Ok(false);
    }
    let input_bytes = fs::read(input).with_context(|| format!("read {}", input.display()))?;
    let signature_bytes =
        fs::read(signature).with_context(|| format!("read {}", signature.display()))?;
    let public_key = read_rsa_public_key(public_key)?;
    Ok(verify_rsa_sha256_bytes(&input_bytes, &signature_bytes, public_key).is_ok())
}

fn read_rsa_private_key(path: &Path) -> Result<RsaPrivateKey> {
    let pem = fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
    RsaPrivateKey::from_pkcs8_pem(&pem)
        .or_else(|_| RsaPrivateKey::from_pkcs1_pem(&pem))
        .with_context(|| format!("parse RSA private key {}", path.display()))
}

fn read_rsa_public_key(path: &Path) -> Result<RsaPublicKey> {
    let pem = fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
    RsaPublicKey::from_public_key_pem(&pem)
        .with_context(|| format!("parse RSA public key {}", path.display()))
}

fn verify_rsa_sha256_bytes(
    input_bytes: &[u8],
    signature_bytes: &[u8],
    public_key: RsaPublicKey,
) -> Result<()> {
    let signature = RsaPkcs1v15Signature::try_from(signature_bytes)
        .context("parse RSA PKCS#1 v1.5 signature")?;
    let verifying_key = VerifyingKey::<Sha256>::new(public_key);
    verifying_key
        .verify(input_bytes, &signature)
        .context("verify RSA/SHA-256 signature")
}

fn extract_tar_gz(archive: &Path, extract_dir: &Path) -> Result<()> {
    let file = fs::File::open(archive).with_context(|| format!("open {}", archive.display()))?;
    let decoder = GzDecoder::new(file);
    let mut archive = tar::Archive::new(decoder);
    archive
        .unpack(extract_dir)
        .with_context(|| format!("extract into {}", extract_dir.display()))?;
    Ok(())
}

fn copy_dir_recursive(source: &Path, destination: &Path) -> Result<()> {
    fs::create_dir_all(destination).with_context(|| format!("create {}", destination.display()))?;
    for entry in fs::read_dir(source).with_context(|| format!("read {}", source.display()))? {
        let entry = entry.with_context(|| format!("read entry in {}", source.display()))?;
        let source_path = entry.path();
        let destination_path = destination.join(entry.file_name());
        let file_type = entry
            .file_type()
            .with_context(|| format!("read file type for {}", source_path.display()))?;
        if file_type.is_dir() {
            copy_dir_recursive(&source_path, &destination_path)?;
        } else if file_type.is_file() {
            fs::copy(&source_path, &destination_path).with_context(|| {
                format!(
                    "copy {} to {}",
                    source_path.display(),
                    destination_path.display()
                )
            })?;
        }
    }
    Ok(())
}

