// ----------------------------------------------------------------------------
// ao2 cp probe-extended — Phase 2 W5 P0 healthz/extended observability probe
// ----------------------------------------------------------------------------
//
// Calls `/api/v1/healthz/extended` on a long-lived ao2-cp-server. If the
// endpoint is not yet deployed (404 / pre-W5-P0 CP), falls back to
// `/api/v1/status` and re-shapes its payload into a healthz-extended-
// compatible envelope so dashboards see a consistent surface across
// pre/post-W5 control planes.
//
// Emits `ao2.cp-healthz-extended-probe.v1` as canonical-JSON evidence.

const CP_PROBE_EXTENDED_SCHEMA: &str = "ao2.cp-healthz-extended-probe.v1";
const CP_HEALTHZ_EXTENDED_SCHEMA: &str = "ao2.cp-healthz-extended.v1";
const CP_STATUS_SCHEMA: &str = "ao2.cp-status.v1";
const CP_RELEASE_SNAPSHOT_SCHEMA: &str = "ao2.cp-release-snapshot.v1";

fn cp(command: CpCommand) -> Result<()> {
    match command {
        CpCommand::ProbeExtended {
            cp_url,
            api_token,
            api_token_env,
            write_json,
            json,
        } => {
            let token = resolve_api_token(api_token.as_deref(), api_token_env.as_deref())?;
            let payload = cp_probe_extended(&cp_url, &token)?;
            if let Some(path) = write_json.as_ref() {
                fs::write(path, format!("{}\n", canonical_json_string(&payload)?))
                    .with_context(|| format!("write {}", path.display()))?;
            }
            if json {
                println!("{}", serde_json::to_string_pretty(&payload)?);
            } else {
                let source = json_string(&payload, "source");
                let schema = json_string(&payload, "observed_schema_version");
                let uptime = payload
                    .get("healthz_extended")
                    .and_then(|h| h.get("uptime_seconds"))
                    .and_then(serde_json::Value::as_f64)
                    .unwrap_or(0.0);
                let last_error = payload
                    .get("healthz_extended")
                    .and_then(|h| h.get("last_error_utc"))
                    .and_then(serde_json::Value::as_str)
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| "null".to_string());
                println!("probe_source={source}");
                println!("observed_schema={schema}");
                println!("uptime_seconds={uptime:.1}");
                println!("last_error_utc={last_error}");
            }
            Ok(())
        }
        CpCommand::ReleaseSnapshot {
            cp_url,
            api_token,
            api_token_env,
            write_json,
            json,
        } => {
            let token = resolve_api_token(api_token.as_deref(), api_token_env.as_deref())?;
            let payload = cp_release_snapshot(&cp_url, &token)?;
            if let Some(path) = write_json.as_ref() {
                fs::write(path, format!("{}\n", canonical_json_string(&payload)?))
                    .with_context(|| format!("write {}", path.display()))?;
            }
            if json {
                println!("{}", serde_json::to_string_pretty(&payload)?);
            } else {
                let cp = json_string(&payload, "cp_url");
                let captured = json_string(&payload, "captured_at_utc");
                let ok = payload
                    .get("summary")
                    .and_then(|s| s.get("ok_count"))
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or(0);
                let errors = payload
                    .get("summary")
                    .and_then(|s| s.get("error_count"))
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or(0);
                let total = payload
                    .get("summary")
                    .and_then(|s| s.get("endpoint_count"))
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or(0);
                println!("cp_url={cp}");
                println!("captured_at_utc={captured}");
                println!("endpoints_ok={ok}/{total}");
                println!("endpoints_error={errors}");
                if let Some(endpoints) = payload.get("endpoints").and_then(|v| v.as_object()) {
                    for (name, value) in endpoints {
                        let ok_flag = value
                            .get("ok")
                            .and_then(serde_json::Value::as_bool)
                            .unwrap_or(false);
                        let schema = value
                            .get("schema")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or("-");
                        let bytes = value
                            .get("body_bytes")
                            .and_then(serde_json::Value::as_u64)
                            .unwrap_or(0);
                        let sha = value
                            .get("body_sha256")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or("-");
                        let short_sha: String = sha.chars().take(12).collect();
                        let status = if ok_flag { "ok" } else { "err" };
                        println!(
                            "  {name}: {status} schema={schema} bytes={bytes} sha256={short_sha}"
                        );
                    }
                }
            }
            Ok(())
        }
    }
}

fn cp_probe_extended(cp_url: &str, api_token: &str) -> Result<serde_json::Value> {
    let base = cp_url.trim_end_matches('/');
    let extended_url = format!("{base}/api/v1/healthz/extended");
    let probed_at = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Micros, true);
    let endpoint = base.to_string();
    if let Ok(extended) = get_json_http(&extended_url, api_token) {
        if extended.get("schema_version").and_then(|v| v.as_str())
            == Some(CP_HEALTHZ_EXTENDED_SCHEMA)
        {
            return Ok(serde_json::json!({
                "schema_version": CP_PROBE_EXTENDED_SCHEMA,
                "probed_at_utc": probed_at,
                "cp_url": endpoint,
                "source": "healthz_extended",
                "observed_schema_version": CP_HEALTHZ_EXTENDED_SCHEMA,
                "healthz_extended": extended,
            }));
        }
    }
    // Fallback: synthesize the healthz-extended shape from /api/v1/status.
    let status_url = format!("{base}/api/v1/status");
    let status = get_json_http(&status_url, api_token).with_context(|| {
        format!("probe {base}: neither /api/v1/healthz/extended nor /api/v1/status responded")
    })?;
    if status.get("schema_version").and_then(|v| v.as_str()) != Some(CP_STATUS_SCHEMA) {
        return Err(anyhow!(
            "unexpected /api/v1/status schema_version: {:?}",
            status.get("schema_version")
        ));
    }
    let synth = serde_json::json!({
        "schema_version": CP_HEALTHZ_EXTENDED_SCHEMA,
        "version": status.get("build").and_then(|b| b.get("version")).cloned()
            .unwrap_or_else(|| serde_json::Value::String(String::new())),
        "uptime_seconds": status.get("uptime_seconds").cloned()
            .unwrap_or_else(|| serde_json::Value::from(0.0)),
        "started_at_utc": serde_json::Value::Null,
        "last_error_utc": serde_json::Value::Null,
        "request_count": status
            .get("requests").and_then(|r| r.get("total")).cloned()
            .unwrap_or_else(|| serde_json::Value::from(0)),
        "error_request_count": status
            .get("requests").and_then(|r| r.get("errors_4xx_5xx")).cloned()
            .unwrap_or_else(|| serde_json::Value::from(0)),
    });
    Ok(serde_json::json!({
        "schema_version": CP_PROBE_EXTENDED_SCHEMA,
        "probed_at_utc": probed_at,
        "cp_url": endpoint,
        "source": "synthesized_from_status",
        "observed_schema_version": CP_STATUS_SCHEMA,
        "healthz_extended": synth,
    }))
}

fn cp_release_snapshot(cp_url: &str, api_token: &str) -> Result<serde_json::Value> {
    let base = cp_url.trim_end_matches('/');
    let captured_at = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Micros, true);
    let endpoints: [(&str, &str); 4] = [
        ("readiness", "/api/v1/release/readiness.json"),
        ("handoff", "/api/v1/release/handoff.json"),
        (
            "support_bundle_status",
            "/api/v1/release/support-bundle.json",
        ),
        ("publication_latest", "/api/v1/release/publication/latest"),
    ];
    let mut documents = serde_json::Map::new();
    let mut ok_count: u64 = 0;
    let mut error_count: u64 = 0;
    for (key, path) in endpoints.iter() {
        let url = format!("{base}{path}");
        let entry = match get_text_http(&url, api_token) {
            Ok(body) => {
                let parsed_schema = serde_json::from_str::<serde_json::Value>(&body)
                    .ok()
                    .and_then(|v| {
                        v.get("schema_version")
                            .or_else(|| v.get("schema"))
                            .and_then(|s| s.as_str())
                            .map(|s| s.to_string())
                    });
                let body_sha256 = sha256_bytes_hex(body.as_bytes());
                ok_count += 1;
                serde_json::json!({
                    "url": url,
                    "ok": true,
                    "schema": parsed_schema,
                    "body_bytes": body.len() as u64,
                    "body_sha256": body_sha256,
                })
            }
            Err(error) => {
                error_count += 1;
                serde_json::json!({
                    "url": url,
                    "ok": false,
                    "error": error.to_string(),
                })
            }
        };
        documents.insert((*key).to_string(), entry);
    }
    Ok(serde_json::json!({
        "schema_version": CP_RELEASE_SNAPSHOT_SCHEMA,
        "captured_at_utc": captured_at,
        "cp_url": base,
        "endpoints": serde_json::Value::Object(documents),
        "summary": {
            "endpoint_count": endpoints.len() as u64,
            "ok_count": ok_count,
            "error_count": error_count,
        },
        "trust_boundary": {
            "control_plane_role": "read_only_observer",
            "mutates_ao_artifacts": false,
        },
    }))
}

fn canonical_json_string(value: &serde_json::Value) -> Result<String> {
    let mut canonical = String::new();
    write_canonical_json_value(&mut canonical, value);
    Ok(canonical)
}

#[allow(clippy::too_many_arguments)]
fn release_sign_provenance(
    version: String,
    macos_archive: Option<PathBuf>,
    linux_archive: PathBuf,
    linux_x86_64_archive: PathBuf,
    windows_archive: PathBuf,
    provenance_dir: PathBuf,
    private_key: PathBuf,
    release_tag: Option<String>,
    json: bool,
) -> Result<()> {
    let mut archives = Vec::new();
    if let Some(macos_archive) = macos_archive {
        archives.push(macos_archive);
    }
    archives.push(linux_archive);
    archives.push(linux_x86_64_archive);
    archives.push(windows_archive);
    for archive in &archives {
        if !archive.is_file() {
            anyhow::bail!("missing release archive: {}", archive.display());
        }
    }
    fs::create_dir_all(&provenance_dir)
        .with_context(|| format!("create {}", provenance_dir.display()))?;
    ensure_rsa_private_key(&private_key, 3072)?;
    let public_key = provenance_dir.join("ao2-release-signing-public.pem");
    derive_public_key_from_private_key(&private_key, &public_key)?;

    let mut archive_entries = Vec::new();
    for archive in &archives {
        let name = archive
            .file_name()
            .and_then(|name| name.to_str())
            .context("archive filename is utf8")?
            .to_string();
        let digest = sha256_file(archive)?;
        atomic_write_text(
            &provenance_dir.join(format!("{name}.sha256")),
            &format!("{digest}  {name}\n"),
        )?;
        sign_file_with_private_key(
            &private_key,
            archive,
            &provenance_dir.join(format!("{name}.sig")),
        )?;
        let signature = format!("{name}.sig");
        let checksum = format!("{name}.sha256");
        archive_entries.push(serde_json::json!({
            "name": name,
            "path": archive,
            "sha256": digest,
            "signature": signature,
            "checksum": checksum
        }));
    }

    let tag = release_tag.unwrap_or_else(|| format!("v{version}"));
    let provenance = serde_json::json!({
        "schema_version": "ao2.release-provenance.v1",
        "package": "ao2",
        "version": version,
        "git_commit": runtime_git_commit(),
        "release_tag": tag,
        "created_at": Utc::now().to_rfc3339_opts(SecondsFormat::Secs, true),
        "signature_algorithm": "RSA-3072/SHA-256",
        "archives": archive_entries
    });
    let provenance_json = provenance_dir.join("ao2-release-provenance.json");
    atomic_write_text(
        &provenance_json,
        &serde_json::to_string_pretty(&provenance)?,
    )?;
    let provenance_signature = provenance_dir.join("ao2-release-provenance.json.sig");
    sign_file_with_private_key(&private_key, &provenance_json, &provenance_signature)?;

    let report = serde_json::json!({
        "schema": "ao2.release-provenance-sign.v1",
        "release_provenance_dir": provenance_dir,
        "release_public_key": public_key,
        "release_provenance": provenance_json,
        "release_provenance_signature": provenance_signature,
        "archive_count": archives.len(),
        "status": "passed"
    });
    if json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "release_provenance_dir={}",
            json_string(&report, "release_provenance_dir")
        );
        println!(
            "release_public_key={}",
            json_string(&report, "release_public_key")
        );
        println!(
            "release_provenance={}",
            json_string(&report, "release_provenance")
        );
        println!("release_provenance_sign=passed");
    }
    Ok(())
}

fn release_verify_provenance(
    macos_archive: Option<PathBuf>,
    linux_archive: PathBuf,
    linux_x86_64_archive: PathBuf,
    windows_archive: PathBuf,
    provenance_dir: PathBuf,
    public_key: Option<PathBuf>,
    json: bool,
) -> Result<()> {
    let public_key =
        public_key.unwrap_or_else(|| provenance_dir.join("ao2-release-signing-public.pem"));
    if !public_key.is_file() {
        anyhow::bail!("missing release public key: {}", public_key.display());
    }
    let mut archives = Vec::new();
    if let Some(macos_archive) = macos_archive {
        archives.push(macos_archive);
    }
    archives.push(linux_archive);
    archives.push(linux_x86_64_archive);
    archives.push(windows_archive);
    let mut results = Vec::new();
    for archive in &archives {
        verify_release_archive_signature(archive, &provenance_dir)?;
        results.push(serde_json::json!({
            "archive": archive,
            "verified": true
        }));
    }
    let provenance = provenance_dir.join("ao2-release-provenance.json");
    let provenance_signature = provenance_dir.join("ao2-release-provenance.json.sig");
    let body = fs::read_to_string(&provenance)
        .with_context(|| format!("read {}", provenance.display()))?;
    let provenance_json: serde_json::Value =
        serde_json::from_str(&body).with_context(|| format!("parse {}", provenance.display()))?;
    if json_string(&provenance_json, "schema_version") != "ao2.release-provenance.v1" {
        anyhow::bail!("invalid release provenance schema");
    }
    if !verify_release_provenance_signature(&provenance, &provenance_signature, &public_key) {
        anyhow::bail!("release provenance signature verification failed");
    }
    let report = serde_json::json!({
        "schema": "ao2.release-provenance-verify.v1",
        "release_provenance_dir": provenance_dir,
        "public_key": public_key,
        "provenance": provenance,
        "provenance_verified": true,
        "archive_count": archives.len(),
        "archives": results,
        "status": "passed"
    });
    if json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "release_provenance_dir={}",
            json_string(&report, "release_provenance_dir")
        );
        println!("release_provenance_verify=passed");
    }
    Ok(())
}

fn ensure_rsa_private_key(private_key: &Path, bits: usize) -> Result<()> {
    if private_key.is_file() {
        read_rsa_private_key(private_key)?;
        return Ok(());
    }
    if let Some(parent) = private_key.parent() {
        fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
    }
    let pem = generate_rsa_private_key_pem(bits)?;
    atomic_write_text(private_key, pem.as_str())?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut permissions = fs::metadata(private_key)?.permissions();
        permissions.set_mode(0o600);
        fs::set_permissions(private_key, permissions)?;
    }
    Ok(())
}

fn generate_rsa_private_key_pem(bits: usize) -> Result<String> {
    std::thread::Builder::new()
        .name("ao2-rsa-keygen".to_string())
        .stack_size(16 * 1024 * 1024)
        .spawn(move || {
            let mut rng = rand::rngs::OsRng;
            let key =
                RsaPrivateKey::new(&mut rng, bits).context("generate RSA release signing key")?;
            key.to_pkcs8_pem(LineEnding::LF)
                .map(|pem| pem.to_string())
                .context("encode RSA private key pem")
        })
        .context("spawn RSA release signing key generator")?
        .join()
        .map_err(|_| anyhow::anyhow!("RSA release signing key generator panicked"))?
}

fn release_compare(
    release_download_dir: PathBuf,
    out_dir: PathBuf,
    signing_key: Option<PathBuf>,
    signer_id: String,
    json: bool,
) -> Result<()> {
    let result = release_comparison_bundle_json(
        release_download_dir,
        out_dir,
        signing_key.as_deref(),
        &signer_id,
    )?;
    if json {
        println!("{}", serde_json::to_string_pretty(&result)?);
    } else {
        println!("release_comparison={}", json_string(&result, "bundle_path"));
        println!(
            "release_history={}",
            json_string(&result, "release_history_path")
        );
        println!(
            "latest_release={}",
            json_string(&result["release_history"]["trend"], "latest_release_tag")
        );
        println!(
            "regressions={}",
            json_u64(&result["release_history"]["trend"], "regression_count")
        );
        if result["support_metadata"]["present"]
            .as_bool()
            .unwrap_or(false)
        {
            println!(
                "signature_verified={}",
                result["support_metadata"]["signature_verified"]
                    .as_bool()
                    .unwrap_or(false)
            );
        }
    }
    Ok(())
}

fn release_comparison_bundle_json(
    release_download_dir: PathBuf,
    out_dir: PathBuf,
    signing_key: Option<&Path>,
    signer_id: &str,
) -> Result<serde_json::Value> {
    let release_history = workbench_release_history_for_dir(release_download_dir.clone())?;
    fs::create_dir_all(&out_dir).with_context(|| format!("create {}", out_dir.display()))?;
    let generated_at_ms = now_unix_ms();
    let bundle_dir = out_dir.join(format!("release-comparison-{generated_at_ms}"));
    fs::create_dir_all(&bundle_dir).with_context(|| format!("create {}", bundle_dir.display()))?;
    let release_history_path = bundle_dir.join("release-history.json");
    let comparison_path = bundle_dir.join("release-comparison.json");
    let sha256_path = bundle_dir.join("SHA256SUMS");
    let mut files = vec![
        serde_json::json!({"path": "release-history.json", "role": "release_history"}),
        serde_json::json!({"path": "release-comparison.json", "role": "portable_bundle"}),
        serde_json::json!({"path": "SHA256SUMS", "role": "checksum_manifest"}),
    ];
    if signing_key.is_some() {
        files.push(serde_json::json!({
            "path": "release-comparison-metadata.json",
            "role": "support_metadata"
        }));
        files.push(serde_json::json!({
            "path": "release-comparison-metadata.json.sig",
            "role": "support_metadata_signature"
        }));
        files.push(serde_json::json!({
            "path": "release-comparison-signing-public.pem",
            "role": "support_metadata_public_key"
        }));
    }
    atomic_write_text(
        &release_history_path,
        &serde_json::to_string_pretty(&release_history)?,
    )?;
    let comparison = serde_json::json!({
        "schema_version": "ao2.release-comparison-bundle.v1",
        "generated_at_ms": generated_at_ms,
        "bundle_dir": bundle_dir,
        "release_download_dir": release_download_dir,
        "release_history": release_history,
        "files": files
    });
    atomic_write_text(
        &comparison_path,
        &serde_json::to_string_pretty(&comparison)?,
    )?;

    let support_metadata = if let Some(signing_key_path) = signing_key {
        sign_release_comparison_metadata(
            &bundle_dir,
            &comparison,
            &comparison_path,
            &release_history_path,
            signing_key_path,
            signer_id,
            generated_at_ms,
        )?
    } else {
        serde_json::json!({
            "present": false,
            "signature_verified": false
        })
    };

    let manifest = json_array(&comparison, "files")
        .iter()
        .filter_map(|file| {
            let relative_path = json_string(file, "path");
            if relative_path == "SHA256SUMS" {
                None
            } else {
                Some(relative_path)
            }
        })
        .map(|relative_path| {
            let file_path = bundle_dir.join(&relative_path);
            Ok(format!("{}  {}\n", sha256_file(&file_path)?, relative_path))
        })
        .collect::<Result<String>>()?;
    atomic_write_text(&sha256_path, &manifest)?;

    let result = serde_json::json!({
        "schema_version": "ao2.release-comparison-bundle.v1",
        "generated_at_ms": generated_at_ms,
        "bundle_dir": json_string(&comparison, "bundle_dir"),
        "bundle_path": comparison_path,
        "release_history_path": release_history_path,
        "release_download_dir": json_string(&comparison, "release_download_dir"),
        "release_history": comparison["release_history"].clone(),
        "support_metadata": support_metadata,
        "files": json_array(&comparison, "files"),
        "sha256_manifest": sha256_path
    });
    Ok(result)
}

fn sign_release_comparison_metadata(
    bundle_dir: &Path,
    comparison: &serde_json::Value,
    comparison_path: &Path,
    release_history_path: &Path,
    signing_key: &Path,
    signer_id: &str,
    generated_at_ms: u64,
) -> Result<serde_json::Value> {
    let metadata_path = bundle_dir.join("release-comparison-metadata.json");
    let signature_path = bundle_dir.join("release-comparison-metadata.json.sig");
    let public_key_path = bundle_dir.join("release-comparison-signing-public.pem");
    derive_public_key_from_private_key(signing_key, &public_key_path)?;
    let trend = &comparison["release_history"]["trend"];
    let metadata = serde_json::json!({
        "schema_version": "ao2.release-comparison-metadata.v1",
        "generated_at_ms": generated_at_ms,
        "signer_id": signer_id,
        "signature_algorithm": "RSA/SHA-256",
        "producer": {
            "package": env!("CARGO_PKG_NAME"),
            "version": env!("CARGO_PKG_VERSION"),
            "git_commit": option_env!("AO2_GIT_COMMIT").unwrap_or("unknown"),
            "target": runtime_target_label()
        },
        "release_comparison_path": comparison_path,
        "release_comparison_sha256": sha256_file(comparison_path)?,
        "release_history_path": release_history_path,
        "release_history_sha256": sha256_file(release_history_path)?,
        "public_key_sha256": sha256_file(&public_key_path)?,
        "release_count": json_u64(trend, "entry_count"),
        "latest_release_tag": json_string(trend, "latest_release_tag"),
        "latest_health_score": json_u64(trend, "latest_health_score"),
        "max_health_score": json_u64(trend, "max_health_score"),
        "attention_count": json_u64(trend, "attention_count"),
        "regression_count": json_u64(trend, "regression_count"),
        "bundle_files": json_array(comparison, "files")
    });
    atomic_write_text(&metadata_path, &serde_json::to_string_pretty(&metadata)?)?;
    sign_file_with_private_key(signing_key, &metadata_path, &signature_path)?;
    release_comparison_metadata_verification_json(bundle_dir)
}

fn release_comparison_metadata_verification_json(bundle_dir: &Path) -> Result<serde_json::Value> {
    let metadata_path = bundle_dir.join("release-comparison-metadata.json");
    let signature_path = bundle_dir.join("release-comparison-metadata.json.sig");
    let public_key_path = bundle_dir.join("release-comparison-signing-public.pem");
    if !metadata_path.exists() && !signature_path.exists() && !public_key_path.exists() {
        return Ok(serde_json::json!({
            "present": false,
            "signature_verified": false
        }));
    }
    if !metadata_path.is_file() || !signature_path.is_file() || !public_key_path.is_file() {
        return Err(anyhow!(
            "release comparison metadata is incomplete; metadata, signature, and public key are all required"
        ));
    }
    let metadata: serde_json::Value = serde_json::from_str(
        &fs::read_to_string(&metadata_path)
            .with_context(|| format!("read {}", metadata_path.display()))?,
    )
    .with_context(|| format!("parse {}", metadata_path.display()))?;
    if json_string(&metadata, "schema_version") != "ao2.release-comparison-metadata.v1" {
        return Err(anyhow!(
            "release comparison metadata must use schema ao2.release-comparison-metadata.v1"
        ));
    }
    let signature_verified =
        verify_file_signature(&metadata_path, &signature_path, &public_key_path)?;
    if !signature_verified {
        return Err(anyhow!(
            "release comparison metadata signature verification failed"
        ));
    }
    Ok(serde_json::json!({
        "present": true,
        "signature_verified": true,
        "metadata_path": metadata_path,
        "signature_path": signature_path,
        "public_key_path": public_key_path,
        "metadata_sha256": sha256_file(&metadata_path)?,
        "signature_sha256": sha256_file(&signature_path)?,
        "public_key_sha256": sha256_file(&public_key_path)?,
        "signer_id": json_string(&metadata, "signer_id"),
        "signature_algorithm": json_string(&metadata, "signature_algorithm"),
        "metadata": metadata
    }))
}

#[allow(clippy::too_many_arguments)]
fn release_support_bundle_build(
    release_assembly: PathBuf,
    readiness: PathBuf,
    handoff: PathBuf,
    cockpit: PathBuf,
    evaluator_decision: PathBuf,
    storage_support: PathBuf,
    replay: PathBuf,
    report_contract_verification: Option<PathBuf>,
    install_verification: PathBuf,
    hosted_release_smoke: PathBuf,
    report_target: Option<PathBuf>,
    report_run_id: Option<String>,
    report: Option<PathBuf>,
    report_index: Option<PathBuf>,
    operator_evidence: PathBuf,
    out_dir: PathBuf,
    json: bool,
) -> Result<()> {
    let result = release_support_bundle_build_json(
        &release_assembly,
        &readiness,
        &handoff,
        &cockpit,
        &evaluator_decision,
        &storage_support,
        &replay,
        report_contract_verification.as_deref(),
        &install_verification,
        &hosted_release_smoke,
        report_target.as_deref(),
        report_run_id.as_deref(),
        report,
        report_index,
        &operator_evidence,
        &out_dir,
    )?;
    if json {
        println!("{}", serde_json::to_string_pretty(&result)?);
    } else {
        println!(
            "release_support_bundle_build={}",
            json_string(&result, "status")
        );
        println!("bundle={}", json_string(&result, "bundle"));
        println!("checksums={}", json_string(&result, "checksums"));
        println!("bundle_sha256={}", json_string(&result, "bundle_sha256"));
        println!(
            "report_contract_verification_source={}",
            json_string(&result, "report_contract_verification_source")
        );
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn release_support_bundle_build_json(
    release_assembly: &Path,
    readiness: &Path,
    handoff: &Path,
    cockpit: &Path,
    evaluator_decision: &Path,
    storage_support: &Path,
    replay: &Path,
    report_contract_verification: Option<&Path>,
    install_verification: &Path,
    hosted_release_smoke: &Path,
    report_target: Option<&Path>,
    report_run_id: Option<&str>,
    report: Option<PathBuf>,
    report_index: Option<PathBuf>,
    operator_evidence: &Path,
    out_dir: &Path,
) -> Result<serde_json::Value> {
    fs::create_dir_all(out_dir).with_context(|| format!("create {}", out_dir.display()))?;
    let bundle_path = out_dir.join("release-support-bundle.json");
    let checksums_path = out_dir.join("SHA256SUMS");
    let (report_contract_verification, report_contract_verification_source) =
        release_support_bundle_report_contract_verification(
            report_contract_verification,
            report_target,
            report_run_id,
            report,
            report_index,
        )?;
    let mut bundle = serde_json::json!({
        "schema_version": "ao2.cp-release-support-bundle.v1",
        "bundle_kind": "release_support",
        "release_assembly": release_support_bundle_read_surface("release_assembly", release_assembly)?,
        "readiness": release_support_bundle_read_surface("readiness", readiness)?,
        "handoff": release_support_bundle_read_surface("handoff", handoff)?,
        "cockpit": release_support_bundle_read_surface("cockpit", cockpit)?,
        "evaluator_decision": release_support_bundle_read_surface("evaluator_decision", evaluator_decision)?,
        "storage_support": release_support_bundle_read_surface("storage_support", storage_support)?,
        "replay": release_support_bundle_read_surface("replay", replay)?,
        "report_contract_verification": report_contract_verification,
        "install_verification": release_support_bundle_read_surface("install_verification", install_verification)?,
        "hosted_release_smoke": release_support_bundle_read_surface("hosted_release_smoke", hosted_release_smoke)?,
        "operator_evidence": release_support_bundle_read_surface("operator_evidence", operator_evidence)?,
        "ci_evidence_index": release_support_bundle_ci_evidence_index(),
        "trust_boundary": {
            "frontend": "Hermes front end / queue / memory surface",
            "governed_backend": "factory-v3 / AO Operator evaluator-closer",
            "trusted_execution": "ao2 signed evidence boundary",
            "role": "read_only_observer",
            "control_plane_role": "read_only_observer",
            "mutates_ao_artifacts": false,
            "control_plane_approves_release": false,
            "release_acceptance_owner": "factory-v3 evaluator-closer"
        },
        "producer": {
            "package": env!("CARGO_PKG_NAME"),
            "version": env!("CARGO_PKG_VERSION"),
            "target": runtime_target_label()
        }
    });
    bundle["portable_bundle_manifest"] = release_support_bundle_portable_manifest(&bundle)?;
    atomic_write_text(&bundle_path, &serde_json::to_string_pretty(&bundle)?)?;
    let bundle_sha256 = canonical_json_sha256(&bundle);
    atomic_write_text(
        &checksums_path,
        &format!("{bundle_sha256}  release-support-bundle.json\n"),
    )?;

    let verification =
        release_support_bundle_verification_json(&bundle_path, Some(checksums_path.as_path()))?;
    if json_string(&verification, "status") != "passed" {
        anyhow::bail!("built release support bundle did not pass verification");
    }

    Ok(serde_json::json!({
        "schema_version": "ao2.release-support-bundle-build.v1",
        "status": "built",
        "bundle": bundle_path.display().to_string(),
        "checksums": checksums_path.display().to_string(),
        "bundle_sha256": bundle_sha256,
        "report_contract_verification_source": report_contract_verification_source,
        "verification": verification
    }))
}

fn release_support_bundle_report_contract_verification(
    report_contract_verification: Option<&Path>,
    report_target: Option<&Path>,
    report_run_id: Option<&str>,
    report: Option<PathBuf>,
    report_index: Option<PathBuf>,
) -> Result<(serde_json::Value, &'static str)> {
    let has_report_inputs = report_target.is_some()
        || report_run_id.is_some()
        || report.is_some()
        || report_index.is_some();
    if let Some(path) = report_contract_verification {
        if has_report_inputs {
            anyhow::bail!(
                "use either --report-contract-verification or --report-target/--report-run-id report inputs, not both"
            );
        }
        let verification =
            release_support_bundle_read_surface("report_contract_verification", path)?;
        return Ok((verification, "explicit_path"));
    }

    let target = report_target.ok_or_else(|| {
        anyhow::anyhow!(
            "support bundle build requires --report-contract-verification or --report-target with --report-run-id"
        )
    })?;
    let run_id = report_run_id.ok_or_else(|| {
        anyhow::anyhow!(
            "support bundle build requires --report-contract-verification or --report-target with --report-run-id"
        )
    })?;
    let verification = report_contract_verification_json(target, run_id, report, report_index)?;
    if json_string(&verification, "status") != "passed" {
        anyhow::bail!("generated report contract verification did not pass");
    }
    Ok((verification, "generated_report_verify"))
}

fn release_support_bundle_read_surface(name: &str, path: &Path) -> Result<serde_json::Value> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("read release support bundle {name}: {}", path.display()))?;
    let value: serde_json::Value = serde_json::from_str(&content)
        .with_context(|| format!("parse release support bundle {name}: {}", path.display()))?;
    if !value.is_object() {
        anyhow::bail!(
            "release support bundle {name} must be a JSON object: {}",
            path.display()
        );
    }
    Ok(value)
}

const RELEASE_SUPPORT_BUNDLE_PUBLIC_SURFACES: [(&str, &str, &str); 9] = [
    (
        "ci_evidence_index",
        "ci_evidence_index",
        "$.ci_evidence_index",
    ),
    (
        "install_verification",
        "install_verification",
        "$.install_verification",
    ),
    (
        "hosted_release_smoke",
        "hosted_release_smoke",
        "$.hosted_release_smoke",
    ),
    ("release_assembly", "release_assembly", "$.release_assembly"),
    ("release_readiness", "readiness", "$.readiness"),
    ("release_candidate_handoff", "handoff", "$.handoff"),
    ("release_cockpit", "cockpit", "$.cockpit"),
    (
        "release_evaluator_decision",
        "evaluator_decision",
        "$.evaluator_decision",
    ),
    (
        "storage_support_bundle",
        "storage_support",
        "$.storage_support",
    ),
];

fn release_support_bundle_portable_manifest(
    bundle: &serde_json::Value,
) -> Result<serde_json::Value> {
    let mut included_surfaces = Vec::new();
    let mut surface_sha256 = serde_json::Map::new();
    for (id, key, path) in RELEASE_SUPPORT_BUNDLE_PUBLIC_SURFACES {
        let surface = bundle
            .get(key)
            .ok_or_else(|| anyhow::anyhow!("missing release support bundle surface {key}"))?;
        let sha256 = canonical_json_sha256(surface);
        surface_sha256.insert(id.to_string(), serde_json::Value::String(sha256.clone()));
        included_surfaces.push(serde_json::json!({
            "id": id,
            "schema_version": json_string(surface, "schema_version"),
            "path": path,
            "sha256": sha256,
        }));
    }

    Ok(serde_json::json!({
        "schema_version": "ao2.cp-release-support-bundle-manifest.v1",
        "included_surfaces": included_surfaces,
        "integrity": {
            "algorithm": "sha256-ao2-cp-canonical-json-v1",
            "scope": "embedded_support_bundle_surfaces",
            "surface_sha256": surface_sha256,
            "verification_plan": {
                "surface_count": RELEASE_SUPPORT_BUNDLE_PUBLIC_SURFACES.len(),
                "expected_fail_closed": true,
                "cross_platform_commands": {
                    "macos_ubuntu": "python3 verify_release_support_bundle.py --json --checksums SHA256SUMS release-support-bundle.json",
                    "windows_powershell": "pwsh -File Verify-ReleaseSupportBundle.ps1 -Json -Checksums SHA256SUMS -Path release-support-bundle.json"
                }
            }
        }
    }))
}

